insert into public.site_settings (id, data) values (1, '{"name":"Virgiawan Listanto","role":{"id":"Desainer & pengembang produk digital, Bandung","en":"Digital product designer & developer, Bandung"},"notice":{"id":"","en":""},"showNotice":false,"email":"virgiawanlistanto088@gmail.com","whatsapp":"6281332623033","whatsappDisplay":"0813 3262 3033","whatsappMessage":{"id":"Halo Virgiawan, saya ingin konsultasi soal sistem untuk bisnis saya.","en":"Hi Virgiawan, I''d like to talk about a system for my business."},"linkedin":"https://www.linkedin.com/in/virgiawan-listanto-5125b3333/","linkedinLabel":"virgiawan-listanto","github":"vanhallen28","photo":{"url":"/media/seed/profile.webp","alt":{"id":"Foto Virgiawan Listanto, berkacamata dan berkemeja hijau zaitun, tersenyum","en":"Photo of Virgiawan Listanto in glasses and an olive shirt, smiling"},"width":880,"height":880},"footer":{"id":"Desain dan kode situs ini juga saya kerjakan sendiri.","en":"I designed and coded this site myself, too."},"seoTitle":{"id":"Virgiawan Listanto · Sistem untuk bisnis","en":"Virgiawan Listanto · Systems for business"},"seoDescription":{"id":"Portofolio Virgiawan Listanto, desainer dan pengembang produk digital di Bandung. Sebelas karya untuk bisnis nyata, dari sistem internal sampai situs merek.","en":"Portfolio of Virgiawan Listanto, a digital product designer and developer in Bandung. Eleven projects for real businesses, from internal systems to brand sites."},"availability":{"show":false,"text":{"id":"Menerima proyek baru","en":"Taking on new projects"}},"stickyCta":{"show":true,"text":{"id":"Chat WhatsApp","en":"Chat on WhatsApp"}},"cv":{"url":"","label":{"id":"Unduh CV (PDF)","en":"Download CV (PDF)"}},"ui":{"skip":{"id":"Langsung ke isi","en":"Skip to content"},"nav":{"works":{"id":"Karya","en":"Work"},"services":{"id":"Layanan","en":"Services"},"process":{"id":"Cara kerja","en":"Process"},"about":{"id":"Tentang","en":"About"},"contact":{"id":"Kontak","en":"Contact"}},"whatsappButton":{"id":"Chat WhatsApp","en":"WhatsApp me"},"menu":{"id":"Menu","en":"Menu"},"backToTop":{"id":"Kembali ke atas","en":"Back to top"}}}'::jsonb) on conflict (id) do nothing;
insert into public.sections (key, data) values ('hero', '{"role":{"id":"Desainer & pengembang produk digital, Bandung","en":"Digital product designer & developer, Bandung"},"title":{"id":"Saya membangun sistem yang menjalankan bisnis Anda: dari toko online sampai payroll.","en":"I build the systems that run your business: from online stores to payroll."},"lede":{"id":"Studio Manager di Invisual Studio. Sebelas karya di halaman ini, dari sistem internal sampai situs merek, saya rancang dan bangun dari tampilan sampai kodenya. Lima di antaranya sudah tayang dan dipakai.","en":"Studio Manager at Invisual Studio. I designed and built the eleven projects on this page, from internal systems to brand sites, from the interface to the code. Five of them are live and in use."},"ctaPrimary":{"id":"Konsultasi gratis via WhatsApp","en":"Free consultation on WhatsApp"},"ctaSecondary":{"id":"Lihat karya","en":"See the work"},"mapCenter":{"id":"Bisnis Anda","en":"Your business"},"mapCaption":{"id":"Denah pameran. Empat sisi bisnis membentuk satu putaran, dan setiap karya adalah stasiun di jalurnya. Pilih stasiun untuk masuk ke ruangnya.","en":"Exhibition map. Four sides of a business form one loop, and each project is a station on its line. Pick a station to enter its room."},"display":{"top":{"id":"Sistem","en":"Systems"},"italic":{"id":"yang menjalankan","en":"that run your"},"bottom":{"id":"Bisnis Anda","en":"business"}},"offer":{"id":"Yang bisa saya bangun: website & landing page, toko online & kasir, portal klien, absensi & payroll","en":"What I build: websites & landing pages, online stores & point of sale, client portals, attendance & payroll"},"badge":{"id":"Masuk ke pameran • {n} ruang karya •","en":"Enter the exhibition • {n} rooms •"},"clients":{"visible":true,"title":{"id":"Proyek untuk","en":"Projects for"},"items":[{"name":"Aliya Syifaa","font":"marcellus","uppercase":false,"projectSlug":"aliya-syifaa"},{"name":"Invisual Studio","font":"host","uppercase":false,"projectSlug":"website-invisual"},{"name":"Biansa","font":"marcellus","uppercase":true,"projectSlug":"biansa"},{"name":"Ciri","font":"cormorant","uppercase":true,"projectSlug":"ciri"},{"name":"Internet Bandung","font":"jakarta","uppercase":false,"projectSlug":"internet-bandung"},{"name":"VALE","font":"vale","uppercase":true,"projectSlug":"vale"},{"name":"Loma","font":"loma","uppercase":true,"projectSlug":"loma"},{"name":"RUA","font":"rua","uppercase":true,"projectSlug":"rua"}]}}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('works', '{"title":{"id":"Karya","en":"Work"},"intro":{"id":"Sebelas ruang, sebelas bisnis. Setiap ruang memakai warna dan huruf milik kliennya, karena sistem yang baik tampil sebagai brand Anda, bukan template saya.","en":"Eleven rooms, eleven businesses. Each room wears its client''s own colours and type, because a good system looks like your brand, not my template."},"allLabel":{"id":"Semua","en":"All"},"roomLabel":{"id":"Ruang","en":"Room"},"previewCta":{"id":"Preview proyek","en":"Preview the project"},"caseCta":{"id":"Lihat studi kasus","en":"Read the case study"},"visitCta":{"id":"Kunjungi situs","en":"Visit the site"},"nextRoom":{"id":"Ruang berikutnya","en":"Next room"},"newTab":{"id":"tab baru","en":"new tab"},"caseLabels":{"client":{"id":"Klien","en":"Client"},"field":{"id":"Bidang","en":"Field"},"role":{"id":"Peran saya","en":"My role"},"year":{"id":"Tahun","en":"Year"},"lines":{"id":"Jalur","en":"Lines"},"site":{"id":"Situs","en":"Site"}}}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('services', '{"visible":true,"title":{"id":"Apa yang bisa saya bangun untuk bisnis Anda","en":"What I can build for your business"},"proofLabel":{"id":"Contoh:","en":"See:"},"items":[{"line":"found","text":{"id":"Website dan landing page yang bisa Anda ubah sendiri, siap untuk mesin pencari, dan mengarahkan pengunjung ke WhatsApp.","en":"Websites and landing pages you can edit yourself, ready for search engines, that send visitors to WhatsApp."},"proof":["website-invisual","internet-bandung","aliya-syifaa"],"price":{"id":"","en":""}},{"line":"sell","text":{"id":"Toko online dengan QRIS, virtual account, dan e-wallet, aplikasi kasir, dan stok yang selalu cocok dengan rak.","en":"Online stores with QRIS, virtual accounts and e-wallets, point-of-sale apps, and stock that always matches the shelf."},"proof":["biansa","ciri","point-pos","internet-bandung"],"price":{"id":"","en":""}},{"line":"serve","text":{"id":"Portal klien dan aplikasi pelanggan: pemesanan, persetujuan, tagihan, dan riwayat, semuanya dari HP.","en":"Client portals and customer apps: bookings, approvals, invoices and history, all from the phone."},"proof":["aliya-syifaa","portal-klien"],"price":{"id":"","en":""}},{"line":"run","text":{"id":"Sistem internal: absensi, payroll, tugas tim, keuangan, dan arsip dokumen di balik satu login.","en":"Internal systems: attendance, payroll, team tasks, finance and documents behind one login."},"proof":["invisual-hris","point-pos","portal-klien"],"price":{"id":"","en":""}}]}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('process', '{"visible":true,"title":{"id":"Cara kerja","en":"How we''ll work"},"steps":[{"title":{"id":"Ngobrol dulu","en":"Start with a chat"},"text":{"id":"Ceritakan cara bisnis Anda berjalan hari ini, lewat WhatsApp atau tatap muka. Saya petakan bagian mana yang paling layak dibuatkan sistem lebih dulu.","en":"Tell me how your business runs today, on WhatsApp or in person. I map out which part is most worth turning into a system first."},"duration":{"id":"","en":""}},{"title":{"id":"Rancangan yang bisa diklik","en":"A design you can click"},"text":{"id":"Sebelum kode ditulis, Anda menerima prototipe yang bisa dicoba di HP dan laptop, seperti preview toko Ciri.","en":"Before any code is written, you get a prototype to try on your phone and laptop, like the Ciri store preview."},"duration":{"id":"","en":""}},{"title":{"id":"Dibangun dan dirilis bertahap","en":"Built and released in steps"},"text":{"id":"Fitur dirilis sedikit demi sedikit supaya Anda bisa mencoba dan memberi masukan sejak awal. Aliya Syifaa melewati 19 versi dalam sembilan hari.","en":"Features ship a little at a time so you can try them and give feedback early. Aliya Syifaa went through 19 versions in nine days."},"duration":{"id":"","en":""}},{"title":{"id":"Serah terima yang jelas","en":"A clear handover"},"text":{"id":"Anda mendapat panduan berbahasa Indonesia yang bisa diikuti langkah demi langkah, dan panel admin untuk mengurus isi tanpa developer.","en":"You get a step-by-step guide in Indonesian and an admin panel to manage content without a developer."},"duration":{"id":"","en":""}}]}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('testimonials', '{"visible":false,"title":{"id":"Kata klien","en":"What clients say"},"items":[]}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('about', '{"visible":true,"title":{"id":"Tentang saya","en":"About me"},"paragraphs":[{"id":"Saya Virgiawan Listanto, Studio Manager di Invisual Studio, Bandung. Selain mengurus studio, saya membangun seluruh sistemnya: website, portal klien, dan HRIS yang dipakai tim setiap hari.","en":"I''m Virgiawan Listanto, Studio Manager at Invisual Studio in Bandung. Besides running the studio, I built all of its systems: the website, the client portal and the HRIS the team uses every day."},{"id":"Di luar studio, saya membantu bisnis lain, dari layanan home care sampai label pakaian, memindahkan pekerjaan harian mereka ke sistem yang rapi. Saya mengerjakan semuanya sendiri: desain tampilan, kode, database, pembayaran, sampai rilis.","en":"Outside the studio I help other businesses, from a home-care service to a clothing label, move their daily work into tidy systems. I handle all of it myself: interface design, code, database, payments and release."}],"skills":[{"id":"Desain antarmuka","en":"Interface design"},{"id":"Next.js & React","en":"Next.js & React"},{"id":"Supabase & PostgreSQL","en":"Supabase & PostgreSQL"},{"id":"Midtrans & Xendit","en":"Midtrans & Xendit"},{"id":"Aplikasi PWA","en":"Installable web apps"}],"experienceTitle":{"id":"Pengalaman","en":"Experience"},"experience":[{"period":{"id":"Sekarang","en":"Present"},"role":{"id":"Studio Manager","en":"Studio Manager"},"org":{"id":"Invisual Studio, Bandung","en":"Invisual Studio, Bandung"},"text":{"id":"Mengurus operasional studio desain sekaligus membangun seluruh sistemnya: website dan CMS, portal klien, dan HRIS yang dipakai 25 orang.","en":"Running a design studio''s operations while building all of its systems: the website and CMS, the client portal, and an HRIS used by 25 people."}},{"period":{"id":"2026","en":"2026"},"role":{"id":"Desainer & pengembang mandiri","en":"Independent designer & developer"},"org":{"id":"Proyek klien","en":"Client projects"},"text":{"id":"Sistem untuk Aliya Syifaa, Biansa, dan Internet Bandung, serta prototipe Ciri dan POINT POS: dari desain tampilan sampai database, pembayaran, dan rilis.","en":"Systems for Aliya Syifaa, Biansa and Internet Bandung, plus the Ciri and POINT POS prototypes: from interface design to database, payments and release."}}]}'::jsonb) on conflict (key) do nothing;
insert into public.sections (key, data) values ('faq', '{"visible":true,"title":{"id":"Pertanyaan yang sering diajukan","en":"Frequently asked questions"},"items":[{"q":{"id":"Berapa biaya membuat sistem untuk bisnis saya?","en":"How much does a system for my business cost?"},"a":{"id":"Tergantung bagian bisnis mana yang perlu dibuatkan sistem. Setelah obrolan pertama yang gratis, Anda menerima penawaran tertulis dengan rincian per fitur dan jadwalnya, jadi angkanya jelas sebelum pekerjaan dimulai.","en":"It depends on which part of your business needs a system. After a free first chat you get a written quote broken down by feature, with a schedule, so the numbers are clear before any work starts."}},{"q":{"id":"Berapa lama pengerjaannya?","en":"How long does it take?"},"a":{"id":"Fitur dirilis bertahap, jadi Anda sudah bisa mencoba bagian pertama sebelum semuanya selesai. Sebagai gambaran, sistem Aliya Syifaa melewati 19 versi dalam sembilan hari pertama. Perkiraan waktu untuk proyek Anda ada di penawaran.","en":"Features ship in steps, so you can try the first part before everything is finished. For reference, the Aliya Syifaa system went through 19 versions in its first nine days. The estimate for your project is in the quote."}},{"q":{"id":"Apakah saya bisa mengubah isi sendiri tanpa developer?","en":"Can I change the content myself, without a developer?"},"a":{"id":"Bisa. Setiap sistem dilengkapi panel admin untuk mengubah teks, harga, gambar, dan data lainnya, plus panduan berbahasa Indonesia yang bisa diikuti langkah demi langkah.","en":"Yes. Every system comes with an admin panel for text, prices, images and other data, plus a step-by-step guide in Indonesian."}},{"q":{"id":"Bisa terima pembayaran QRIS, virtual account, atau e-wallet?","en":"Can it take QRIS, virtual account or e-wallet payments?"},"a":{"id":"Bisa. Toko dan portal yang saya bangun memakai payment gateway seperti Midtrans dan Xendit, dan status lunas baru berubah setelah pembayarannya terkonfirmasi.","en":"Yes. The stores and portals I build use payment gateways such as Midtrans and Xendit, and an order only counts as paid once the payment is confirmed."}},{"q":{"id":"Sistemnya disimpan di mana? Ada biaya bulanan?","en":"Where is the system hosted? Is there a monthly fee?"},"a":{"id":"Biasanya situsnya di Vercel dan databasenya di Supabase. Biayanya mengikuti paket penyedia dan besarnya trafik, dibayar langsung ke penyedia, dan perkiraannya saya cantumkan di penawaran. Saya sarankan akun-akun itu atas nama bisnis Anda, supaya sistemnya sepenuhnya milik Anda.","en":"Usually the site runs on Vercel and the database on Supabase. The cost follows the provider''s plan and your traffic, is paid to the provider directly, and I include an estimate in the quote. I recommend putting those accounts in your business''s name, so the system is fully yours."}},{"q":{"id":"Bagaimana kalau ada masalah setelah selesai?","en":"What if something breaks after launch?"},"a":{"id":"Setiap perbaikan dikirim sebagai paket update bernomor versi dengan panduan pasangnya, jadi jelas apa yang berubah. Masa dukungan setelah rilis disepakati di penawaran.","en":"Every fix ships as a numbered update package with install steps, so it''s always clear what changed. The support period after launch is agreed in the quote."}}]}'::jsonb) on conflict (key) do nothing;
