insert into public.projects (id, slug, sort, published, data) values ('73b8623d-c113-5ea0-ab63-d3aac3dee57e', 'aliya-syifaa', 1, true, '{"name":"Aliya Syifaa","mapLabel":"Aliya Syifaa","mapSlot":1,"titleFont":"marcellus","titleStyle":{"size":"xl","uppercase":false,"weight":400,"tracking":0},"meta":{"id":"Home care terapi Islami, 2026","en":"Islamic home-care therapy, 2026"},"text":{"id":"Layanan terapi yang datang ke rumah pasien butuh lebih dari sekadar website. Saya membangun satu sistem untuk seluruh alurnya: form konsultasi bertanda tangan, aplikasi pasien, aplikasi terapis, dan panel admin untuk jadwal, pembayaran, dan isi situs.","en":"A therapy service that visits patients at home needed more than a website. I built one system for the whole flow: a signed consultation form, a patient app, a therapist app, and an admin panel for schedules, payments and site content."},"lines":["serve","found"],"theme":{"wall":"#15241E","ink":"#F8EADA","muted":"#B9C3B6","accent":"#D4B16E","btnBg":"#D4B16E","btnInk":"#15241E"},"facts":[{"value":"4","label":{"id":"aplikasi dalam satu sistem","en":"apps in one system"}},{"value":"19","label":{"id":"versi dirilis dalam 9 hari","en":"versions shipped in 9 days"}},{"value":"6","label":{"id":"langkah anamnesa dengan tanda tangan","en":"step intake form with signature"}}],"status":null,"liveUrl":"https://www.aliyasyifaa.com/","liveLabel":"aliyasyifaa.com","liveNote":null,"previewUrl":"/preview/aliya-syifaa.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/aliya-admin.webp","alt":{"id":"Panel admin Aliya Syifaa: pesanan baru, kunjungan aktif, pendapatan, dan keluhan terbanyak","en":"Aliya Syifaa admin panel: new bookings, active visits, revenue and top complaints"},"width":1600,"height":911}},{"role":"phone","image":{"url":"/media/seed/aliya-hp-beranda.webp","alt":{"id":"Aplikasi pasien: kunjungan berikutnya dan daftar layanan","en":"Patient app: next visit and list of services"},"width":390,"height":844}}],"brand":null,"pattern":"none","motion":"arch","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('adb2f26d-61cb-549f-894d-957fd98ee546', 'invisual-hris', 2, true, '{"name":"Invisual HRIS","mapLabel":"Invisual HRIS","mapSlot":7,"titleFont":"archivo","titleStyle":{"size":"lg","uppercase":true,"weight":400,"tracking":-0.01},"meta":{"id":"Sistem internal studio, Invisual Studio, 2026","en":"Internal studio system, Invisual Studio, 2026"},"text":{"id":"Satu portal untuk 25 orang di studio: absensi dengan selfie dan lokasi, payroll periode 21 sampai 20, task tracker, chat dengan panggilan suara, kanvas desain bersama, keuangan, dan arsip dokumen. Satu login menggantikan setumpuk aplikasi langganan.","en":"One portal for the studio''s 25 people: selfie-and-location attendance, payroll on the 21st-to-20th cycle, a task tracker, chat with voice calls, a shared design canvas, finance and a document vault. One login replaces a stack of subscriptions."},"lines":["run"],"theme":{"wall":"#204DC6","ink":"#FFF6E0","muted":"#C9D4F6","accent":"#FFD23F","btnBg":"#FFD23F","btnInk":"#111111"},"facts":[{"value":"25","label":{"id":"orang memakainya setiap hari","en":"people use it every day"}},{"value":"8","label":{"id":"modul di balik satu login","en":"modules behind one login"}},{"value":"47rb","label":{"id":"baris kode, dikerjakan sendiri","en":"lines of code, built solo"}}],"status":null,"liveUrl":"","liveLabel":"","liveNote":{"id":"Versi live di hris.invisual.studio khusus tim","en":"The live version at hris.invisual.studio is team only"},"previewUrl":"/preview/hris.html","layout":"back-desk","visuals":[{"role":"back","image":{"url":"/media/seed/hris-heatmap.webp","alt":{"id":"Timesheet heatmap kehadiran harian per karyawan","en":"Daily attendance timesheet heatmap per employee"},"width":1600,"height":887}},{"role":"desk","image":{"url":"/media/seed/hris-dasbor.webp","alt":{"id":"Dasbor HR: jumlah hadir, terlambat, WFH, log absensi live","en":"HR dashboard: present, late, WFH counts and live attendance log"},"width":1600,"height":903}}],"brand":null,"pattern":"none","motion":"slide","result":{"id":"Satu login menggantikan sekitar enam aplikasi langganan yang dulu dipakai terpisah.","en":"One login replaced about six subscription apps the studio used to run separately."}}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('5a58e7d3-0970-5cba-8abd-ffb43dc286b5', 'biansa', 3, true, '{"name":"Biansa","mapLabel":"Biansa","mapSlot":4,"titleFont":"marcellus","titleStyle":{"size":"xl","uppercase":false,"weight":400,"tracking":0.04},"meta":{"id":"Toko online sleepwear, Tasikmalaya, 2026","en":"Sleepwear online store, Tasikmalaya, 2026"},"text":{"id":"Toko milik sendiri untuk label sleepwear lokal, bukan lapak marketplace. Pembeli bisa checkout tanpa akun dan membayar lewat virtual account, QRIS, atau e-wallet. Harga selalu dihitung ulang di server, dan pesanan baru dianggap lunas setelah payment gateway mengonfirmasi.","en":"A store of its own for a local sleepwear label, not a marketplace listing. Shoppers check out as guests and pay by virtual account, QRIS or e-wallet. Prices are always recalculated on the server, and an order only counts as paid once the payment gateway confirms it."},"lines":["sell"],"theme":{"wall":"#ECE6DB","ink":"#2A241D","muted":"#5F5B45","accent":"#6E6A52","btnBg":"#2A241D","btnInk":"#F5F1E9"},"facts":[{"value":"34","label":{"id":"halaman toko dan admin","en":"store and admin pages"}},{"value":"4","label":{"id":"gaya beranda yang dipilih pemilik","en":"homepage styles the owner can pick"}},{"value":"4","label":{"id":"lapis cek sebelum status lunas","en":"checks before an order is paid"}}],"status":{"id":"Belum tayang, menunggu keputusan klien","en":"Not live yet, awaiting the client''s go-ahead"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/biansa.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/biansa-beranda.webp","alt":{"id":"Beranda Biansa: model memakai outer karamel dalam bingkai lengkung, judul Nyaman itu tidak harus mahal","en":"Biansa homepage: a model in a caramel outer inside an arched frame, headline Nyaman itu tidak harus mahal"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/biansa-hp-produk.webp","alt":{"id":"Halaman produk Outer Piping Espresso versi HP: foto utama dan deretan thumbnail galeri","en":"Outer Piping Espresso product page on phone: main photo and the gallery thumbnails"},"width":600,"height":1300}}],"brand":{"logoUrl":"/media/seed/biansa-logo.svg","swatches":[{"name":"Oat","color":"#D9CDB8"},{"name":"Sage","color":"#A8A88F"},{"name":"Ivory","color":"#EFE9DD"},{"name":"Espresso","color":"#4A3B2E"},{"name":"Indigo","color":"#3A4356"},{"name":"Clay","color":"#B08968"}],"note":{"id":"14 layar toko dan admin ada di preview UI","en":"14 store and admin screens in the UI preview"}},"pattern":"none","motion":"curtain","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('f93ddd77-c3ef-5bfd-8c21-1c671327edc5', 'portal-klien', 4, true, '{"name":"Portal Klien","mapLabel":"Portal Klien","mapSlot":8,"titleFont":"unbounded","titleStyle":{"size":"md","uppercase":false,"weight":800,"tracking":-0.02},"meta":{"id":"Portal klien studio desain, Invisual Studio, 2026","en":"Design studio client portal, Invisual Studio, 2026"},"text":{"id":"Klien studio desain tidak perlu lagi mencari draf di WhatsApp dan Drive. Di portal ini mereka melihat progres, menaruh catatan revisi langsung di gambar, menandatangani kontrak, dan membayar tagihan. Tim studio mengatur semuanya dari papan Kanban.","en":"A design studio''s clients no longer dig through WhatsApp and Drive for drafts. In this portal they follow progress, pin revision notes on the artwork, sign the contract and pay invoices. The studio runs it all from a Kanban board."},"lines":["serve","run"],"theme":{"wall":"#2243CE","ink":"#FFF4E0","muted":"#D6DDFF","accent":"#D1F360","btnBg":"#D1F360","btnInk":"#110B28"},"facts":[{"value":"1","label":{"id":"link persetujuan, tanpa perlu login","en":"approval link, no login needed"}},{"value":"2","label":{"id":"jenis revisi dengan kuota per tahap","en":"revision types with per-stage quotas"}},{"value":"3","label":{"id":"cara bayar: QRIS, VA, e-wallet","en":"ways to pay: QRIS, VA, e-wallet"}}],"status":{"id":"Preview proyek menyusul","en":"Project preview coming soon"},"liveUrl":"http://portal.invisual.studio/","liveLabel":"portal.invisual.studio","liveNote":null,"previewUrl":"","layout":"two-phones","visuals":[{"role":"phone","image":{"url":"/media/seed/portal-top.webp","alt":{"id":"Beranda portal klien: status proyek dan kartu proyek","en":"Client portal home: project status and project card"},"width":640,"height":1023}},{"role":"phone","image":{"url":"/media/seed/portal-progres.webp","alt":{"id":"Progres tahapan, batas feedback 48 jam, sisa revisi","en":"Stage progress, 48-hour feedback window, revisions left"},"width":640,"height":1015}}],"brand":null,"pattern":"checker","motion":"spread","result":{"id":"Dimulai dari audit keamanan: 66 uji hak akses yang gagal kini semuanya lolos, sebelum fitur baru ditambahkan.","en":"It started with a security audit: 66 failing access tests now all pass, before any new feature was added."}}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('917b706b-98ac-5382-ac9e-6928f98f53ec', 'ciri', 5, true, '{"name":"Ciri","mapLabel":"Ciri","mapSlot":5,"titleFont":"cormorant","titleStyle":{"size":"xxl","uppercase":true,"weight":500,"tracking":0.02},"meta":{"id":"Toko perhiasan perak AG925, 2026","en":"AG925 silver jewellery store, 2026"},"text":{"id":"Arah visual dan prototipe toko untuk koleksi perak AG925: huruf grafit, abu perak, tanpa warna aksen, supaya foto produknya yang berkilau. Tiga puluh lima halaman yang bisa diklik, masing-masing dalam versi desktop dan HP, untuk ditinjau klien sebelum dibangun.","en":"Visual direction and a clickable store prototype for an AG925 silver collection: graphite type, silver greys and no accent colour, so the photography brings the shine. Thirty-five clickable pages, each in desktop and phone versions, for the client to review before the build."},"lines":["sell"],"theme":{"wall":"#2F3031","ink":"#F9F9F9","muted":"#BFC3C7","accent":"#E4E6E8","btnBg":"#F9F9F9","btnInk":"#2F3031"},"facts":[{"value":"13","label":{"id":"perhiasan dalam 8 bentuk","en":"pieces in 8 forms"}},{"value":"35","label":{"id":"halaman, desktop dan HP","en":"pages, desktop and phone"}},{"value":"0","label":{"id":"warna aksen, perak yang bicara","en":"accent colours, the silver speaks"}}],"status":{"id":"Dalam review klien","en":"In client review"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/ciri.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/ciri-home.webp","alt":{"id":"Beranda Ciri: tangan memakai cincin perak, judul Your Personal Mark","en":"Ciri homepage: a hand wearing a silver ring, headline Your Personal Mark"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/ciri-hp.webp","alt":{"id":"Halaman produk Hollow Ring versi HP","en":"Hollow Ring product page on phone"},"width":600,"height":1298}}],"brand":null,"pattern":"none","motion":"focus","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('5ea9fd41-1964-5919-b1f3-b5405a6c86dc', 'website-invisual', 6, true, '{"name":"Website Invisual","mapLabel":"Website Invisual","mapSlot":2,"titleFont":"host","titleStyle":{"size":"lg","uppercase":false,"weight":700,"tracking":-0.03},"meta":{"id":"Situs dan CMS studio desain, Bandung, 2026","en":"Design studio site and CMS, Bandung, 2026"},"text":{"id":"Situs portofolio studio yang seluruh isinya bisa diubah sendiri oleh tim, dalam dua bahasa. Ada form brief proyek satu pertanyaan per layar, kotak masuk, statistik pengunjung, dan editor blog yang memeriksa 14 poin SEO sebelum artikel terbit.","en":"A studio portfolio site whose every word the team can edit, in two languages. It has a one-question-per-screen project brief, an inbox, visitor statistics, and a blog editor that checks 14 SEO points before an article goes live."},"lines":["found"],"theme":{"wall":"#101011","ink":"#F2F2F2","muted":"#A6A6AC","accent":"#F65294","btnBg":"#F65294","btnInk":"#101011"},"facts":[{"value":"14","label":{"id":"poin SEO dicek sebelum terbit","en":"SEO checks before publishing"}},{"value":"2","label":{"id":"bahasa, satu alamat","en":"languages, one address"}},{"value":"20+","label":{"id":"paket pembaruan dikirim","en":"update packages shipped"}}],"status":null,"liveUrl":"https://invisual.studio/","liveLabel":"invisual.studio","liveNote":null,"previewUrl":"/preview/web-invi.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/web-contact.webp","alt":{"id":"Halaman kontak Invisual Studio versi Bahasa Indonesia, mode gelap","en":"Invisual Studio contact page in Indonesian, dark mode"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/web-hp.webp","alt":{"id":"Halaman kontak di HP","en":"Contact page on phone"},"width":600,"height":1298}}],"brand":null,"pattern":"none","motion":"tilt","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('36416adb-ba98-597e-8c59-4fef26390a55', 'internet-bandung', 7, true, '{"name":"Internet Bandung","mapLabel":"Internet Bandung","mapSlot":3,"titleFont":"jakarta","titleStyle":{"size":"lg","uppercase":false,"weight":800,"tracking":-0.03},"meta":{"id":"Landing page penjualan internet rumah, Bandung, 2026","en":"Home internet sales landing page, Bandung, 2026"},"text":{"id":"Landing page yang mengarahkan setiap pengunjung ke WhatsApp, karena di sanalah pembeli memutuskan. Pemilik mengubah harga, promo, dan kota jangkauan dari panel admin, dan perubahannya langsung tampil. Setiap klik WhatsApp tercatat dari tombol mana asalnya.","en":"A landing page that sends every visitor to WhatsApp, because that''s where buyers decide. The owner edits prices, promos and coverage cities from an admin panel and the changes appear instantly. Every WhatsApp click is logged with the button it came from."},"lines":["found","sell"],"theme":{"wall":"#D8006F","ink":"#FFFFFF","muted":"#FFF0F7","accent":"#FFC24B","btnBg":"#FFC24B","btnInk":"#26202E"},"facts":[{"value":"8","label":{"id":"panel admin tanpa kode","en":"no-code admin panels"}},{"value":"3","label":{"id":"pilihan durasi paket: 1, 6, 12 bulan","en":"plan lengths: 1, 6 or 12 months"}},{"value":"1","label":{"id":"tujuan untuk setiap tombol: WhatsApp","en":"destination for every button: WhatsApp"}}],"status":null,"liveUrl":"https://www.internetbandung.com/","liveLabel":"internetbandung.com","liveNote":null,"previewUrl":"/preview/internet-bandung.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/intbdg-paket.webp","alt":{"id":"Pilihan paket internet dengan tab 1, 6, dan 12 bulan","en":"Internet plans with 1, 6 and 12-month tabs"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/intbdg-hp.webp","alt":{"id":"Paket internet di HP dengan tombol WhatsApp","en":"Internet plans on phone with a WhatsApp button"},"width":600,"height":1298}}],"brand":null,"pattern":"glow","motion":"signal","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('4c7b3202-46ba-55fe-aed8-7695aac2189b', 'point-pos', 8, true, '{"name":"POINT POS","mapLabel":"POINT POS","mapSlot":6,"titleFont":"lora","titleStyle":{"size":"md","uppercase":false,"weight":600,"tracking":0.01},"meta":{"id":"Kasir dan inventori coffee shop, 2026","en":"Point of sale and inventory for coffee shops, 2026"},"text":{"id":"Kasir coffee shop yang tahu isi gudangnya. Setiap menu punya resep, jadi satu cappuccino yang terjual langsung mengurangi stok kopi dan susu, sementara HPP dan margin terhitung sendiri. Pesanan diteruskan ke layar barista, dan stock opname bisa memakai blind count supaya hitungan fisik tetap jujur.","en":"A coffee-shop point of sale that knows what''s in the storeroom. Every menu item has a recipe, so each cappuccino sold deducts coffee and milk from stock while cost of goods and margin calculate themselves. Orders flow to a barista screen, and stock counts can run blind so the physical count stays honest."},"lines":["sell","run"],"theme":{"wall":"#F1EBE1","ink":"#2B2620","muted":"#6B6355","accent":"#2F6BFF","btnBg":"#2B2620","btnInk":"#FBF8F2"},"facts":[{"value":"6","label":{"id":"modul: kasir, barista, dashboard, riwayat, inventori, opname","en":"modules: till, barista, dashboard, history, inventory, counts"}},{"value":"4","label":{"id":"cara bayar: tunai, QRIS, kartu, e-wallet","en":"ways to pay: cash, QRIS, card, e-wallet"}},{"value":"1","label":{"id":"resep per menu, stok bahan terpotong sendiri","en":"recipe per item, ingredients deduct themselves"}}],"status":{"id":"Prototipe interaktif, bisa langsung dicoba","en":"Interactive prototype you can try now"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/point-pos.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/point-kasir.webp","alt":{"id":"Layar kasir POINT: menu kopi, pesanan berisi varian dan add-on, pajak PB1, dan pilihan bayar","en":"POINT till screen: coffee menu, order with variants and add-ons, PB1 tax and payment options"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/point-hp.webp","alt":{"id":"Katalog menu POINT di HP","en":"POINT menu catalogue on phone"},"width":600,"height":1298}}],"brand":null,"pattern":"none","motion":"print","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('b3e12ca6-5f31-564b-bb02-2067017def95', 'vale', 9, true, '{"name":"VALE","mapLabel":"VALE","mapSlot":9,"titleFont":"vale","titleStyle":{"size":"xxl","uppercase":true,"weight":400,"tracking":0.02},"meta":{"id":"Golf clubhouse bertema ksatria, Invisual Studio, 2026","en":"Knight-themed golf clubhouse, Invisual Studio, 2026"},"text":{"id":"Situs untuk golf clubhouse yang menjadikan setiap pegolf seorang ksatria. Berandanya peta kerajaan yang bisa digeser dan diperbesar, dengan enam landmark untuk ditemukan. Enam bab bercerita dari lapangan sampai keanggotaan, dan tee time dipesan dalam enam langkah dengan tiket yang terisi sambil memilih.","en":"A site for a golf clubhouse where every golfer becomes a knight. The homepage is a map of the realm you can drag and zoom, with six landmarks to discover. Six chapters run from the course to the membership, and a tee time books in six steps with a ticket that fills in as you choose."},"lines":["found","serve"],"theme":{"wall":"#5B3C34","ink":"#FED7AB","muted":"#EAD3A8","accent":"#F3CC9E","btnBg":"#FED7AB","btnInk":"#3E2A24"},"facts":[{"value":"7","label":{"id":"halaman: peta kerajaan dan enam bab","en":"pages: the realm map and six chapters"}},{"value":"6","label":{"id":"landmark untuk ditemukan di peta","en":"landmarks to discover on the map"}},{"value":"50","label":{"id":"gambar vektor dalam satu file","en":"vector drawings in a single file"}}],"status":{"id":"Preview desain, belum tayang","en":"Design preview, not live yet"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/vale.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/vale-peta.webp","alt":{"id":"Beranda VALE: peta kerajaan bergaya cetak dengan enam landmark, kompas, dan daftar Legend of the Realm","en":"VALE homepage: a printed-style map of the realm with six landmarks, a compass and the Legend of the Realm list"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/vale-hp.webp","alt":{"id":"Bab I di HP: Every golfer becomes a knight, dengan ilustrasi ksatria","en":"Chapter I on phone: Every golfer becomes a knight, with a knight illustration"},"width":600,"height":1298}}],"brand":null,"pattern":"none","motion":"unfold","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('042b1844-a06f-5a50-8149-8032ea9936c4', 'loma', 10, true, '{"name":"Loma","mapLabel":"Loma","mapSlot":10,"titleFont":"loma","titleStyle":{"size":"xxl","uppercase":true,"weight":400,"tracking":0.06},"meta":{"id":"Restoran Amerika Latin, Lima, Invisual Studio, 2026","en":"Latin American restaurant, Lima, Invisual Studio, 2026"},"text":{"id":"Situs untuk ruang makan Amerika Latin di Lima yang tenang tapi berani. Fotonya melengkung halus saat digulir, carta berisi 33 menu bisa dijelajah per kategori, kisahnya diceritakan lewat material ruangan, dan meja dipesan dalam enam langkah yang menutup hari Senin dengan sendirinya.","en":"A site for a Latin American dining room in Lima, quiet but bold. The photographs bend gently as you scroll, the 33-item carta browses by course, the story is told through the room''s materials, and a table books in six steps that close Mondays on their own."},"lines":["found","serve"],"theme":{"wall":"#161513","ink":"#BAB2A5","muted":"#8C857B","accent":"#BAB2A5","btnBg":"#BAB2A5","btnInk":"#161513"},"facts":[{"value":"4","label":{"id":"halaman: beranda, carta, historia, reservasi","en":"pages: home, carta, historia, reservations"}},{"value":"33","label":{"id":"menu di carta, makanan dan minuman","en":"items on the carta, food and drink"}},{"value":"6","label":{"id":"langkah memesan meja","en":"steps to book a table"}}],"status":{"id":"Preview desain, belum tayang","en":"Design preview, not live yet"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/loma.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/loma-hero.webp","alt":{"id":"Beranda Loma: lampu dinding hangat di ruang makan gelap, wordmark Loma besar di bawah","en":"Loma homepage: a warm wall lamp in a dark dining room, the large Loma wordmark below"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/loma-hp.webp","alt":{"id":"Tujuh menu signature Loma di HP, masing-masing dengan fotonya","en":"Loma''s seven signature plates on phone, each with its photo"},"width":600,"height":1298}}],"brand":null,"pattern":"glow","motion":"glow","result":null}'::jsonb) on conflict do nothing;
insert into public.projects (id, slug, sort, published, data) values ('ea7d720a-1d02-5600-b3b3-175d3728dc65', 'rua', 11, true, '{"name":"RUA","mapLabel":"RUA","mapSlot":11,"titleFont":"rua","titleStyle":{"size":"xxl","uppercase":true,"weight":400,"tracking":0},"meta":{"id":"Kafe Vietnam, Saigon, Invisual Studio, 2026","en":"Vietnamese café, Saigon, Invisual Studio, 2026"},"text":{"id":"Situs untuk kafe Vietnam di Saigon dengan maskot kura-kura yang menjadi pelayan. Menu bisa dipesan untuk satu meja lalu dikirim ke kasir sebagai tiket bernomor, papan Open/Closed mengikuti jam Saigon, dan setiap bagian bergerak seperti animasi stop-motion merek RUA.","en":"A site for a Vietnamese café in Saigon whose turtle mascot works as the server. The menu orders for the whole table and goes to the counter as a numbered ticket, the Open/Closed sign follows Saigon time, and every section moves like RUA''s own stop-motion animations."},"lines":["found","serve"],"theme":{"wall":"#BA0C0C","ink":"#FFF7C7","muted":"#F9D816","accent":"#F9D816","btnBg":"#F9D816","btnInk":"#5B0808"},"facts":[{"value":"17","label":{"id":"makanan dan minuman di menu","en":"dishes and drinks on the menu"}},{"value":"13","label":{"id":"wajah kura-kura untuk setiap suasana","en":"turtle faces for every mood"}},{"value":"96","label":{"id":"gambar vektor dalam satu file","en":"vector drawings in a single file"}}],"status":{"id":"Preview desain, belum tayang","en":"Design preview, not live yet"},"liveUrl":"","liveLabel":"","liveNote":null,"previewUrl":"/preview/rua.html","layout":"desk-phone","visuals":[{"role":"desk","image":{"url":"/media/seed/rua-hero.webp","alt":{"id":"Beranda RUA: wordmark merah besar di latar kuning, maskot kura-kura memegang menu dan menyapa Xin chào","en":"RUA homepage: a large red wordmark on yellow, the turtle mascot holding a menu and saying Xin chào"},"width":1600,"height":1000}},{"role":"phone","image":{"url":"/media/seed/rua-hp.webp","alt":{"id":"Come, we eat di HP: judul kuning di latar merah dan tiga kura-kura pelayan","en":"Come, we eat on phone: a yellow headline on red and three turtle servers"},"width":600,"height":1298}}],"brand":null,"pattern":"none","motion":"pop","result":null}'::jsonb) on conflict do nothing;
insert into public.case_studies (project_slug, published, data) select 'aliya-syifaa', true, '{"subtitle":{"id":"Satu sistem untuk layanan home care terapi Islami: dari form konsultasi sampai kuitansi.","en":"One system for an Islamic home-care therapy service: from the consultation form to the receipt."},"labels":{"client":"Aliya Syifaa","field":{"id":"Home care terapi Islami","en":"Islamic home-care therapy"},"role":{"id":"Desain, pengembangan, database, rilis","en":"Design, development, database, release"},"year":"2026"},"cover":{"url":"/media/seed/aliya-laptop.webp","alt":{"id":"Aplikasi pasien Aliya Syifaa di dalam bingkai ponsel, dengan pilihan tema terang dan gelap","en":"Aliya Syifaa patient app in a phone frame, with light and dark theme options"},"width":1280,"height":800},"theme":{"wall":"#FBF7F0","ink":"#15241E","muted":"#55635B","accent":"#9E7B36","btnBg":"#15241E","btnInk":"#F8EADA"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Aliya Syifaa mengirim terapis bersertifikat ke rumah pasien untuk bekam, ruqyah syar''iyyah, refleksi, konsultasi herbal, dan terapi lainnya. Layanan seperti ini melibatkan empat pihak sekaligus: calon pasien, pasien dan keluarganya, terapis di lapangan, dan admin. Masing-masing butuh tampilan sendiri, tapi datanya harus satu.","en":"Aliya Syifaa sends certified therapists to patients'' homes for cupping, ruqyah, reflexology, herbal consultations and other therapies. A service like this involves four parties at once: prospective patients, patients and their families, therapists in the field, and the admin. Each needs its own view, but the data has to be one."},{"id":"Karena menyimpan data kesehatan, sistemnya juga harus menjaga privasi sesuai UU Pelindungan Data Pribadi, dan cara bayarnya harus mengikuti kebiasaan pasien: bayar setelah terapi, tunai ke terapis atau transfer.","en":"Because it holds health data, the system also has to protect privacy under Indonesia''s personal data protection law, and payments have to follow how patients actually pay: after the session, in cash to the therapist or by bank transfer."}]},{"type":"features","title":{"id":"Satu sistem, empat pintu","en":"One system, four doors"},"items":[{"title":{"id":"Situs dan form konsultasi","en":"Website and consultation form"},"text":{"id":"Calon pasien membaca layanan lalu mengisi anamnesa enam langkah: keluhan, riwayat kesehatan, gaya hidup, pin lokasi, dan tanda tangan persetujuan. Tanpa perlu membuat akun.","en":"Prospective patients read about the services, then fill in a six-step intake: complaints, health history, lifestyle, a location pin and a signed consent. No account needed."},"images":[{"url":"/media/seed/aliya-web.webp","alt":{"id":"Beranda situs Aliya Syifaa: Terapi Islami, datang ke rumah Anda","en":"Aliya Syifaa homepage: Islamic therapy, at your home"},"width":1400,"height":1280}]},{"title":{"id":"Aplikasi pasien","en":"Patient app"},"text":{"id":"Pasien dan keluarganya memesan kunjungan, melihat jadwal, membaca catatan terapis, dan membayar tagihan. Aplikasinya bisa dipasang di layar utama HP.","en":"Patients and their families book visits, check the schedule, read the therapist''s notes and pay invoices. The app installs on the phone''s home screen."},"images":[{"url":"/media/seed/aliya-hp-layanan.webp","alt":{"id":"Daftar layanan dengan harga dan durasi","en":"Service list with prices and durations"},"width":390,"height":844},{"url":"/media/seed/aliya-hp-jadwal.webp","alt":{"id":"Jadwal kunjungan mendatang dan riwayat","en":"Upcoming visits and history"},"width":390,"height":844}]},{"title":{"id":"Aplikasi terapis","en":"Therapist app"},"text":{"id":"Terapis melihat kunjungan hari ini lengkap dengan rute Google Maps, mencatat tanda vital dan skala nyeri sebelum dan sesudah terapi, lalu menerbitkan tagihan atau mencatat pembayaran tunai. Uang tunai yang belum disetor terlihat jelas.","en":"Therapists see today''s visits with Google Maps routes, record vital signs and pain scores before and after each session, then issue the invoice or log a cash payment. Cash not yet handed in stays visible."},"images":[]},{"title":{"id":"Panel admin","en":"Admin panel"},"text":{"id":"Admin mengatur pesanan, pasien, pembayaran, layanan, tim terapis, dan isi situs. Statistik pengunjungnya berjalan tanpa cookie dan tanpa data pribadi.","en":"The admin manages bookings, patients, payments, services, the therapist team and site content. Visitor statistics run without cookies or personal data."},"images":[{"url":"/media/seed/aliya-statistik.webp","alt":{"id":"Statistik situs: pengunjung per hari, sumber pengunjung, kalender kunjungan","en":"Site statistics: visitors per day, traffic sources, visit calendar"},"width":1600,"height":903}]}]},{"type":"flow","title":{"id":"Alur layanan","en":"The service flow"},"steps":[{"id":"Calon pasien mengisi konsultasi online","en":"A prospective patient fills in the online consultation"},{"id":"Admin menjadwalkan dan menugaskan terapis","en":"The admin schedules it and assigns a therapist"},{"id":"Terapis datang dan mencatat terapinya","en":"The therapist visits and records the session"},{"id":"Tagihan terbit: tunai, transfer, atau bayar nanti","en":"The invoice goes out: cash, transfer or pay later"},{"id":"Kuitansi bisa dibuka dan dicetak dari link","en":"A receipt opens and prints from a link"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Harga tidak bisa diakali dari HP","en":"Prices can''t be tampered with from a phone"},"text":{"id":"Harga layanan dan ongkos transport selalu dihitung ulang di database. Diskon terapis punya batas, dan setiap perubahan tercatat.","en":"Service prices and transport fees are always recalculated in the database. Therapist discounts have a cap, and every change is logged."}},{"title":{"id":"Data kesehatan tidak tersimpan di perangkat","en":"Health data never stays on the device"},"text":{"id":"Aplikasinya tetap terbuka saat sinyal lemah, tapi halaman yang berisi data kesehatan tidak pernah disimpan offline.","en":"The app still opens on a weak signal, but pages with health data are never stored offline."}},{"title":{"id":"Ongkos transport mengikuti jarak","en":"Transport fees follow the distance"},"text":{"id":"Biaya transport dihitung dari jarak lokasi pasien ke klinik, berdasarkan zona yang diatur admin sendiri.","en":"Transport is priced from the patient''s distance to the clinic, using zones the admin sets."}},{"title":{"id":"Pemilik mengatur akun sendiri","en":"The owner manages accounts"},"text":{"id":"Admin menambah terapis atau admin baru lewat link undangan sekali pakai, tanpa developer. Sistem memastikan selalu ada minimal satu admin.","en":"The admin adds therapists or other admins through single-use invite links, no developer needed. The system makes sure there is always at least one admin."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"51","label":{"id":"halaman di empat aplikasi","en":"pages across four apps"}},{"value":"19","label":{"id":"versi dalam sembilan hari","en":"versions in nine days"}},{"value":"30","label":{"id":"aturan akses di database","en":"access rules in the database"}},{"value":"3","label":{"id":"peran pengguna plus pengunjung","en":"user roles plus visitors"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Supabase (PostgreSQL), Leaflet & OpenStreetMap, PWA, Vercel.","en":"Built with Next.js, React, TypeScript, Supabase (PostgreSQL), Leaflet & OpenStreetMap, PWA, Vercel."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'aliya-syifaa') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'invisual-hris', true, '{"subtitle":{"id":"Satu portal internal untuk 25 orang di studio desain, dari absen pagi sampai slip gaji.","en":"One internal portal for a design studio''s 25 people, from the morning clock-in to the payslip."},"labels":{"client":"Invisual Studio","field":{"id":"Studio desain visual","en":"Visual design studio"},"role":{"id":"Desain, pengembangan, database, rilis","en":"Design, development, database, release"},"year":"2026"},"cover":{"url":"/media/seed/hris-dasbor.webp","alt":{"id":"Dasbor HR: jumlah karyawan hadir, terlambat, dan WFH, dengan log absensi live","en":"HR dashboard: counts of staff present, late and working from home, with a live attendance log"},"width":1600,"height":903},"theme":{"wall":"#FFF6E0","ink":"#111111","muted":"#4A4F63","accent":"#204DC6","btnBg":"#204DC6","btnInk":"#FFF6E0"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Invisual Studio adalah studio desain visual di Bandung dengan sekitar 25 orang, dan saya bekerja di sana sebagai Studio Manager. Absensi, tugas, obrolan tim, dan berkas studio dulu tersebar di sekitar enam aplikasi langganan yang terpisah, jadi saya membangun satu portal untuk menggantikannya.","en":"Invisual Studio is a visual design studio in Bandung with about 25 people, and I work there as Studio Manager. Attendance, tasks, team chat and studio files used to live in about six separate subscription apps, so I built one portal to replace them."},{"id":"Aturannya harus mengikuti cara kerja di Indonesia: periode gaji tanggal 21 sampai 20, libur nasional dan cuti bersama sesuai SKB 3 Menteri, izin WFH dan WFC, izin terlambat, dan lembur yang ditukar menjadi libur pengganti. Semua jam dihitung dalam WIB.","en":"The rules had to match how work runs in Indonesia: a pay period from the 21st to the 20th, national holidays and collective leave set by joint ministerial decree, remote-work and late-arrival permissions, and overtime traded for time off in lieu. Every hour runs on Jakarta time."}]},{"type":"features","title":{"id":"Satu login untuk seluruh studio","en":"One login for the whole studio"},"items":[{"title":{"id":"Absensi dengan selfie dan lokasi","en":"Attendance with a selfie and location"},"text":{"id":"Karyawan absen masuk dan pulang dengan selfie, dan sistem mencocokkan lokasinya dengan area yang ditentukan. HR melihat siapa yang hadir, terlambat, atau WFH saat itu juga, lengkap dengan heatmap timesheet, kalender cuti, dan daftar kejanggalan.","en":"Staff clock in and out with a selfie, and the system checks their location against a set area. HR sees who is in, late or working from home as it happens, with a timesheet heatmap, a leave calendar and a list of anomalies."},"images":[{"url":"/media/seed/hris-heatmap.webp","alt":{"id":"Timesheet heatmap: kehadiran harian setiap karyawan untuk periode 21 Oktober sampai 20 November","en":"Timesheet heatmap: each employee''s daily attendance for the 21 October to 20 November period"},"width":1600,"height":887}]},{"title":{"id":"Payroll periode 21 sampai 20","en":"Payroll on the 21st-to-20th cycle"},"text":{"id":"Gaji disusun per periode dan melewati tiga tahap: draf, final, lalu kirim. Slip gaji PDF terkirim ke email karyawan dan bisa diunduh lagi dari profil masing-masing. Pengumuman juga bisa dikirim massal lewat email atau WhatsApp.","en":"Payroll runs per period through three stages: draft, final, then send. PDF payslips go to each employee''s email and can be downloaded again from their profile. Announcements can go out in bulk by email or WhatsApp."},"images":[]},{"title":{"id":"Tugas, chat, dan kanvas bersama","en":"Tasks, chat and a shared canvas"},"text":{"id":"Task tracker menampilkan pekerjaan sebagai tabel, Kanban, kalender, beban kerja, atau timeline. Chat tim punya channel, panggilan suara dan video, serta berbagi layar. Di kanvas desain, beberapa orang bisa menggambar dan berkomentar di file yang sama pada waktu yang sama.","en":"The task tracker shows work as a table, Kanban board, calendar, workload view or timeline. Team chat has channels, voice and video calls and screen sharing. On the design canvas, several people can draw and comment on the same file at the same time."},"images":[]},{"title":{"id":"Keuangan dan arsip studio","en":"Studio finance and records"},"text":{"id":"Pemilik mencatat transaksi, pendapatan, dan anggaran per kategori, lalu membaca laporannya di modul yang sama. Peringatan muncul saat satu kategori melewati 80% anggarannya. Dokumen perusahaan, email, dan daftar langganan software tersimpan di satu arsip.","en":"The owner records transactions, income and budgets by category, then reads the reports in the same module. An alert appears when a category passes 80% of its budget. Company documents, email and the list of software subscriptions sit in one archive."},"images":[{"url":"/media/seed/hris-keuangan.webp","alt":{"id":"Ringkasan keuangan studio: pemasukan, pengeluaran, laba rugi, saldo kumulatif, peringatan anggaran, dan tren 6 bulan","en":"Studio finance summary: income, expenses, profit and loss, running balance, budget alerts and a six-month trend"},"width":1600,"height":901}]}]},{"type":"flow","title":{"id":"Satu periode kerja","en":"One working period"},"steps":[{"id":"Karyawan absen masuk dengan selfie","en":"Staff clock in with a selfie"},{"id":"HR menyetujui izin WFH, cuti, dan terlambat dari satu antrean","en":"HR approves remote work, leave and late requests from one queue"},{"id":"Tim mengerjakan tugas dan menyetor bukti kerja harian di chat","en":"The team works through tasks and posts daily proof of work in chat"},{"id":"Lembur tercatat dan menjadi jatah libur pengganti","en":"Overtime is logged and turns into time off in lieu"},{"id":"Di akhir periode, payroll difinalkan dan slip gaji terkirim","en":"At the end of the period, payroll is finalised and payslips go out"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Gaji hanya terlihat oleh yang berhak","en":"Salaries stay with the people who need them"},"text":{"id":"Data gaji disembunyikan dari daftar karyawan, jadi rekan kerja tidak bisa melihat gaji satu sama lain. Ini salah satu perbaikan dari audit keamanan Oktober 2026.","en":"Salary data is hidden from the staff directory, so colleagues can''t see each other''s pay. It''s one of the fixes from the October 2026 security audit."}},{"title":{"id":"Selfie absen tidak disimpan selamanya","en":"Attendance selfies don''t stay forever"},"text":{"id":"Foto selfie disimpan di folder tertutup, hanya bisa dibuka lewat link yang kedaluwarsa dalam satu jam, dan terhapus otomatis setelah tujuh hari. Bukti kerja harian di chat terhapus sendiri setelah 30 hari.","en":"Selfies sit in a private folder, open only through links that expire within an hour, and are deleted automatically after seven days. Daily proof-of-work screenshots in chat delete themselves after 30 days."}},{"title":{"id":"Periode gaji yang sudah final terkunci","en":"Finalised pay periods are locked"},"text":{"id":"Setelah payroll difinalkan, database menolak perubahan apa pun pada periode itu. Angka di slip yang sudah terkirim selalu sama dengan angka di sistem.","en":"Once payroll is finalised, the database refuses any change to that period. The figures on a payslip that has gone out always match the system."}},{"title":{"id":"Akses mengikuti peran","en":"Access follows the role"},"text":{"id":"Ada lima peran: HR atau admin, pemilik, manajer tracker, anggota tim, dan freelancer. Freelancer hanya bisa memakai chat, dan karyawan hanya bisa mengirim pesan pribadi ke HR atau manajer.","en":"There are five roles: HR or admin, owner, tracker manager, team member and freelancer. Freelancers can only use chat, and staff can only send direct messages to HR or a manager."}}]},{"type":"results","title":{"id":"Hasilnya","en":"The outcome"},"items":[{"before":"± 6 aplikasi","after":"1 login","label":{"id":"untuk absensi, tugas, chat, dan berkas studio","en":"for attendance, tasks, chat and studio files"}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"25","label":{"id":"orang memakainya setiap hari","en":"people use it every day"}},{"value":"8","label":{"id":"modul di balik satu login","en":"modules behind one login"}},{"value":"5","label":{"id":"peran pengguna dengan akses berbeda","en":"user roles with different access"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Supabase (PostgreSQL), LiveKit untuk panggilan suara dan video, PWA, Vercel.","en":"Built with Next.js, React, TypeScript, Supabase (PostgreSQL), LiveKit for voice and video calls, PWA, Vercel."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'invisual-hris') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'biansa', true, '{"subtitle":{"id":"Toko online milik sendiri untuk label sleepwear lokal di Tasikmalaya, dari katalog sampai pembayaran.","en":"An online store of its own for a local sleepwear label in Tasikmalaya, from catalogue to payment."},"labels":{"client":"Biansa Style","field":{"id":"Fesyen sleepwear dan daily wear","en":"Sleepwear and daily-wear fashion"},"role":{"id":"Desain, pengembangan, database, pembayaran","en":"Design, development, database, payments"},"year":"2026"},"cover":{"url":"/media/seed/biansa-beranda.webp","alt":{"id":"Beranda Biansa: model memakai outer karamel dalam bingkai lengkung, dengan judul Nyaman itu tidak harus mahal","en":"Biansa homepage: a model in a caramel outer inside an arched frame, under the headline Nyaman itu tidak harus mahal"},"width":1600,"height":1000},"theme":{"wall":"#F5F1E9","ink":"#2A241D","muted":"#5F5B45","accent":"#6E6A52","btnBg":"#2A241D","btnInk":"#F5F1E9"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Biansa Style adalah label sleepwear dan daily wear di Tasikmalaya: kimono, daster, dan piyama seharga Rp 65 ribu sampai Rp 445 ribu. Pemiliknya ingin toko sendiri, bukan lapak marketplace, dengan cara bayar yang biasa dipakai pembeli Indonesia dan isi toko yang bisa diubah tanpa developer.","en":"Biansa Style is a sleepwear and daily-wear label in Tasikmalaya: kimonos, house dresses and pyjamas priced from Rp 65,000 to Rp 445,000. The owner wanted a store of their own rather than a marketplace listing, with the payment methods Indonesian shoppers already use and content they can change without a developer."},{"id":"Toko ini berawal dari POINT Store, template toko yang saya bangun dari tujuh layar arah visual. Merek Biansa dipasang dengan mengubah satu file, tanpa membongkar kode lainnya. Tokonya belum tayang dan sedang menunggu keputusan klien.","en":"The store started as POINT Store, a shop template I built from seven visual-direction screens. Biansa''s branding went in by editing a single file, without touching the rest of the code. The store isn''t live yet and is waiting on the client''s decision."}]},{"type":"features","title":{"id":"Etalase dan dapur toko","en":"Storefront and back office"},"items":[{"title":{"id":"Etalase yang bisa diatur pemilik","en":"A storefront the owner can shape"},"text":{"id":"Pemilik memilih satu dari empat gaya beranda: editorial, etalase, marquee, atau mozaik. Pembeli menyaring dan mengurutkan produk, melihat galeri foto dan pilihan warna, tahu ukuran mana yang habis, dan membuka panduan ukuran tanpa pindah halaman.","en":"The owner picks one of four homepage styles: editorial, shop window, marquee or mosaic. Shoppers filter and sort products, browse the photo gallery and colour options, see which sizes are sold out, and open the size guide without leaving the page."},"images":[{"url":"/media/seed/biansa-produk.webp","alt":{"id":"Halaman produk Outer Piping Espresso: galeri foto dengan thumbnail, enam pilihan warna, ukuran XXL habis, dan sisa stok","en":"Outer Piping Espresso product page: photo gallery with thumbnails, six colour options, size XXL sold out, and the stock left"},"width":1600,"height":1144}]},{"title":{"id":"Checkout tanpa akun","en":"Guest checkout"},"text":{"id":"Pembeli bisa checkout tanpa membuat akun, lalu membayar lewat virtual account, GoPay, ShopeePay, atau QRIS. Transfer bank manual juga diterima dan ditandai lunas oleh admin. Harga sudah termasuk PPN 11%, dan setiap pesanan bisa dilacak lewat timeline status.","en":"Shoppers can check out without an account and pay by virtual account, GoPay, ShopeePay or QRIS. Manual bank transfers work too, marked as paid by the admin. Prices include 11% VAT, and every order can be followed on a status timeline."},"images":[{"url":"/media/seed/biansa-hp-tas.webp","alt":{"id":"Tas belanja di HP: tiga produk dengan ukuran dan jumlahnya, lalu ringkasan","en":"Shopping bag on a phone: three products with their sizes and quantities, then the summary"},"width":600,"height":1300},{"url":"/media/seed/biansa-hp-checkout.webp","alt":{"id":"Checkout tanpa akun di HP: nama, nomor WhatsApp, dan alamat pengiriman","en":"Guest checkout on a phone: name, WhatsApp number and delivery address"},"width":600,"height":1300}]},{"title":{"id":"Pesanan dan stok","en":"Orders and stock"},"text":{"id":"Admin menyaring pesanan menurut tahap: belum bayar, perlu dibuat, perlu dikirim, dan terkirim, lalu mengisi nomor resi. Stok bisa diisi massal dari file Excel, dengan pratinjau sebelum disimpan. Dasbor menampilkan omzet, jumlah terjual, dan stok menipis.","en":"The admin filters orders by stage: unpaid, to make, to ship and shipped, then adds the tracking number. Stock can be bulk-imported from an Excel file, with a preview before saving. The dashboard shows revenue, units sold and low stock."},"images":[{"url":"/media/seed/biansa-dasbor.webp","alt":{"id":"Dasbor admin Biansa: pendapatan 30 hari, pesanan, produk terjual, stok menipis, terlaris, dan pesanan terbaru","en":"Biansa admin dashboard: 30-day revenue, orders, units sold, low stock, best sellers and latest orders"},"width":1600,"height":1144}]},{"title":{"id":"Isi toko di tangan pemilik","en":"Content in the owner''s hands"},"text":{"id":"Pemilik mengubah beranda, halaman, dan blog sendiri. Pajak, ongkir, dan promo diatur dengan pratinjau keranjang yang langsung berubah, dan 200 aksi admin terakhir tercatat di log audit.","en":"The owner edits the homepage, pages and blog directly. Tax, shipping and promos are set with a live cart preview, and the last 200 admin actions are kept in an audit log."},"images":[{"url":"/media/seed/biansa-blog-admin.webp","alt":{"id":"Editor blog di admin: judul, slug, ringkasan, dan gambar sampul tulisan","en":"Blog editor in the admin: the post''s title, slug, summary and cover image"},"width":1600,"height":1000}]}]},{"type":"flow","title":{"id":"Perjalanan satu pesanan","en":"The life of an order"},"steps":[{"id":"Pembeli memilih produk, warna, dan ukuran","en":"A shopper picks a product, colour and size"},{"id":"Checkout tanpa akun dan bayar lewat VA, e-wallet, atau QRIS","en":"They check out as a guest and pay by VA, e-wallet or QRIS"},{"id":"Payment gateway mengonfirmasi, pesanan berubah lunas","en":"The payment gateway confirms and the order turns paid"},{"id":"Admin membuat dan mengirim pesanan, lalu mengisi nomor resi","en":"The admin makes and ships the order, then adds the tracking number"},{"id":"Pembeli memantau status pesanan dari halaman pelacakan","en":"The shopper follows the order on its tracking page"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Harga selalu dihitung ulang di server","en":"Prices are always recalculated on the server"},"text":{"id":"Harga di keranjang pembeli tidak pernah dipakai mentah-mentah. Setiap checkout menghitung ulang harga dan total di server, jadi harga tidak bisa diakali dari browser.","en":"The prices in a shopper''s cart are never taken at face value. Every checkout recalculates prices and totals on the server, so nobody can tamper with them from the browser."}},{"title":{"id":"Status lunas hanya dari payment gateway","en":"Only the payment gateway can mark an order paid"},"text":{"id":"Pesanan baru dianggap lunas setelah payment gateway mengonfirmasi. Konfirmasinya dicek keasliannya, tidak bisa diproses dua kali, nominalnya harus sama dengan total pesanan, dan status hanya bisa maju, tidak mundur.","en":"An order only counts as paid once the payment gateway confirms it. Each confirmation is checked for authenticity, can''t be processed twice, must match the order total exactly, and can only move the status forward."}},{"title":{"id":"Stok tercatat sebagai riwayat","en":"Stock is kept as a history"},"text":{"id":"Angka stok tidak pernah ditimpa begitu saja. Setiap barang masuk dan keluar tercatat, jadi selisih stok selalu bisa ditelusuri ke pesanan, impor, atau penyesuaian admin.","en":"Stock figures are never simply overwritten. Every item in and out is recorded, so any difference can be traced back to an order, an import or an admin adjustment."}},{"title":{"id":"Pembaruan tidak menimpa isi pemilik","en":"Updates don''t overwrite the owner''s edits"},"text":{"id":"Alat pembaruan membandingkan versi lama, versi baru, dan versi milik toko sebelum memasang apa pun. Bagian yang sudah diubah pemilik tidak ditimpa, dan foto toko tidak disentuh.","en":"The update tool compares the old version, the new version and the store''s own copy before installing anything. Parts the owner has changed stay as they are, and the store''s photos are left alone."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"34","label":{"id":"halaman toko dan admin","en":"store and admin pages"}},{"value":"4","label":{"id":"gaya beranda pilihan pemilik","en":"homepage styles the owner can pick"}},{"value":"4","label":{"id":"lapis cek sebelum status lunas","en":"checks before an order counts as paid"}},{"value":"5","label":{"id":"cara bayar, termasuk transfer manual","en":"ways to pay, including manual transfer"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Tailwind CSS, Supabase (PostgreSQL), Midtrans, Cloudinary.","en":"Built with Next.js, React, TypeScript, Tailwind CSS, Supabase (PostgreSQL), Midtrans, Cloudinary."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'biansa') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'portal-klien', true, '{"subtitle":{"id":"Portal tempat klien studio desain mengikuti proyek, menyetujui draf, dan membayar tagihan dari HP.","en":"A portal where a design studio''s clients follow their project, approve drafts and pay invoices from their phone."},"labels":{"client":"Invisual Studio","field":{"id":"Studio desain visual","en":"Visual design studio"},"role":{"id":"Desain, pengembangan, database, rilis","en":"Design, development, database, release"},"year":"2026"},"cover":null,"theme":{"wall":"#FFF4E0","ink":"#110B28","muted":"#4B4766","accent":"#2243CE","btnBg":"#2243CE","btnInk":"#FFF4E0"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Invisual Studio mengerjakan identitas visual, ilustrasi, dan kemasan untuk banyak klien sekaligus. Tanpa satu tempat bersama, draf, revisi, kontrak, dan tagihan tercecer di WhatsApp, email, dan Drive, dan klien sulit tahu proyeknya sudah sampai mana atau apa yang perlu mereka lakukan berikutnya.","en":"Invisual Studio handles visual identity, illustration and packaging for many clients at once. Without one shared place, drafts, revisions, contracts and invoices get scattered across WhatsApp, email and Drive, and clients struggle to tell where their project stands or what they need to do next."},{"id":"Pekerjaan saya di portal ini berawal dari audit keamanan. Data di 11 tabel belum dibatasi menurut siapa yang boleh melihatnya, dan 66 dari 92 uji hak akses gagal. Setelah diperbaiki, semuanya lolos. Dari situ portalnya tumbuh lewat puluhan paket fitur menjadi alur kerja studio yang utuh.","en":"My work on the portal began with a security audit. Data in 11 tables had no limits on who could see it, and 66 of 92 access tests failed. After the fixes, every test passed. From there the portal grew through dozens of feature batches into the studio''s full workflow."}]},{"type":"features","title":{"id":"Dua sisi, satu proyek","en":"Two sides, one project"},"items":[{"title":{"id":"Beranda klien","en":"Client home"},"text":{"id":"Klien langsung melihat status proyek dan satu langkah berikutnya yang perlu mereka ambil. Ada hitung mundur batas feedback 48 jam, sisa kuota revisi, jadwal tahapan, tanda tangan kontrak, dan laporan PDF.","en":"Clients see the project status and the one next step they need to take. There''s a countdown for the 48-hour feedback window, the revisions left, a stage timeline, contract signing and a PDF report."},"images":[{"url":"/media/seed/portal-top.webp","alt":{"id":"Beranda portal klien di HP: status proyek dan kartu proyek dengan target selesai","en":"Client portal home on a phone: project status and a project card with its target date"},"width":640,"height":1023},{"url":"/media/seed/portal-progres.webp","alt":{"id":"Lima tahap progres proyek, batas feedback 48 jam, sisa revisi, dan menu tanda tangan kontrak di HP","en":"Five project stages, the 48-hour feedback window, revisions left and the contract signing menu, on a phone"},"width":640,"height":1015}]},{"title":{"id":"Draf dan revisi","en":"Drafts and revisions"},"text":{"id":"Klien menyetujui draf atau meminta revisi mayor atau minor, menaruh catatan langsung di titik gambar, dan membandingkan dua versi dengan slider. Catatan revisi yang panjang diringkas otomatis menjadi paling banyak enam poin, dan file final diunduh dalam satu ZIP.","en":"Clients approve a draft or ask for a major or minor revision, pin notes right on the artwork, and compare two versions with a slider. Long revision notes are summarised automatically into six points at most, and final files download as one ZIP."},"images":[]},{"title":{"id":"Tagihan dan chat","en":"Invoices and chat"},"text":{"id":"Tagihan dibayar lewat QRIS, virtual account, atau e-wallet, atau dengan mengunggah bukti transfer, lalu bisa dicetak sebagai PDF. Chat dengan studio punya terjemahan otomatis Indonesia dan Inggris, jadi klien dan tim bisa menulis dalam bahasa masing-masing.","en":"Invoices are paid by QRIS, virtual account or e-wallet, or by uploading proof of transfer, and print as PDFs. Chat with the studio has automatic Indonesian-English translation, so clients and the team can each write in their own language."},"images":[]},{"title":{"id":"Ruang kerja studio","en":"The studio''s workspace"},"text":{"id":"Tim studio memindahkan proyek di papan Kanban: briefing dan MoU, desain, review dan revisi, lalu selesai. Halaman ringkasan menampilkan piutang, pendapatan bulanan, tagihan lewat jatuh tempo, dan fokus hari ini, lengkap dengan tombol pengingat ke klien.","en":"The studio team moves projects across a Kanban board: briefing and MoU, design, review and revision, then done. The overview shows receivables, monthly revenue, overdue invoices and today''s focus, with a button to send the client a reminder."},"images":[]}]},{"type":"flow","title":{"id":"Alur satu proyek","en":"How a project runs"},"steps":[{"id":"Studio membuka proyek dan klien menandatangani kontrak di portal","en":"The studio opens the project and the client signs the contract in the portal"},{"id":"Studio mengunggah draf, klien mendapat notifikasi di aplikasi, email, dan HP","en":"The studio uploads a draft and the client is notified in the app, by email and on their phone"},{"id":"Klien menyetujui atau meminta revisi dalam batas 48 jam","en":"The client approves or asks for revisions within 48 hours"},{"id":"Studio merevisi, dan sisa kuota revisi terlihat oleh kedua pihak","en":"The studio revises, and both sides can see how many revisions are left"},{"id":"Klien membayar tagihan dan mengunduh file final","en":"The client pays the invoice and downloads the final files"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Ruang studio hanya untuk email studio","en":"The studio side is for studio emails only"},"text":{"id":"Akses ke ruang studio dicek dengan aturan yang sama di aplikasi dan di database. Alamat email yang sekadar meniru domain studio ditolak, jadi orang luar tidak bisa masuk ke data seluruh klien.","en":"Access to the studio side is checked by the same rule in the app and in the database. An email address that merely imitates the studio''s domain is rejected, so outsiders can''t reach every client''s data."}},{"title":{"id":"Link persetujuan bisa dicabut","en":"Approval links can be revoked"},"text":{"id":"Pihak klien yang tidak punya akun, misalnya atasan yang harus menyetujui, bisa membuka draf lewat link rahasia. Link itu kedaluwarsa dalam 14 hari dan bisa dicabut studio kapan saja.","en":"People on the client''s side without an account, such as a manager who has to sign off, can open the draft through a private link. The link expires after 14 days and the studio can revoke it at any time."}},{"title":{"id":"Lunas setelah payment gateway mengonfirmasi","en":"Paid only when the payment gateway confirms"},"text":{"id":"Tagihan baru berubah lunas setelah payment gateway mengonfirmasi pembayaran. Konfirmasi yang tidak membawa kode rahasia studio ditolak, jadi status lunas tidak bisa dipalsukan.","en":"An invoice only turns paid after the payment gateway confirms the payment. Confirmations without the studio''s secret code are rejected, so nobody can fake a paid status."}},{"title":{"id":"Setiap bug punya tes sendiri","en":"Every bug gets its own test"},"text":{"id":"Setiap bug yang pernah ditemukan diberi tes dengan namanya sendiri supaya tidak muncul lagi, dan 145 skenario hak akses diuji langsung di database.","en":"Every bug ever found gets a named test so it can''t come back, and 145 access scenarios are tested directly against the database."}}]},{"type":"results","title":{"id":"Hasilnya","en":"The outcome"},"items":[{"before":"66 gagal","after":"0 gagal","label":{"id":"uji hak akses yang gagal dari 92 di audit awal, setelah diperbaiki","en":"failing access tests out of 92 in the first audit, after the fixes"}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"145","label":{"id":"skenario hak akses kini diuji otomatis","en":"access scenarios now tested automatically"}},{"value":"3","label":{"id":"cara bayar online: QRIS, VA, e-wallet","en":"ways to pay online: QRIS, VA, e-wallet"}},{"value":"14","label":{"id":"hari masa berlaku link persetujuan","en":"days an approval link stays valid"}},{"value":"4","label":{"id":"tahap di papan Kanban studio","en":"stages on the studio''s Kanban board"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Supabase (PostgreSQL), Xendit, Resend, PWA.","en":"Built with Next.js, React, TypeScript, Supabase (PostgreSQL), Xendit, Resend, PWA."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'portal-klien') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'ciri', true, '{"subtitle":{"id":"Arah visual dan prototipe toko online untuk koleksi perhiasan perak AG925, kini dalam review klien.","en":"Visual direction and an online store prototype for an AG925 sterling-silver collection, now in client review."},"labels":{"client":"Ciri","field":{"id":"Perhiasan perak","en":"Silver jewellery"},"role":{"id":"Arah visual, desain UI, prototipe","en":"Visual direction, UI design, prototype"},"year":"2026"},"cover":{"url":"/media/seed/ciri-home.webp","alt":{"id":"Beranda Ciri: tangan memakai cincin perak, dengan judul Your Personal Mark","en":"Ciri homepage: a hand wearing a silver ring under the headline Your Personal Mark"},"width":1600,"height":1000},"theme":{"wall":"#F6F6F5","ink":"#2F3031","muted":"#5B5F63","accent":"#6B6F73","btnBg":"#2F3031","btnInk":"#F9F9F9"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Ciri menjual koleksi perhiasan perak sterling AG925: 13 perhiasan dalam 8 bentuk, terdiri dari cincin, anting, dan kalung. Perhiasan perak dijual lewat fotonya, jadi tampilan toko harus memberi ruang untuk kilau logamnya, bukan bersaing dengannya.","en":"Ciri sells an AG925 sterling-silver collection: 13 pieces in 8 forms across rings, earrings and necklaces. Silver jewellery sells through its photos, so the store has to give the metal room to shine, not compete with it."},{"id":"Sebelum toko dibangun, klien perlu melihat dan mencobanya lebih dulu. Saya menyerahkan satu file preview berisi 35 halaman yang bisa diklik, masing-masing dalam versi desktop dan HP. Klien sedang meninjaunya sekarang, dan tokonya belum dibangun.","en":"Before anything gets built, the client needs to see and try the store. I handed over a single preview file with 35 clickable pages, each in a desktop and a phone version. The client is reviewing it now, and the store itself hasn''t been built yet."}]},{"type":"features","title":{"id":"Toko yang bisa diklik","en":"A store you can click through"},"items":[{"title":{"id":"Arah visual tanpa warna aksen","en":"A visual direction with no accent colour"},"text":{"id":"Huruf grafit dan abu perak, tanpa warna aksen sama sekali, supaya foto perhiasan yang paling menonjol. Judul memakai Cormorant yang klasik, sedangkan teks memakai Inter Tight yang ringkas dan mudah dibaca di HP.","en":"Graphite type and silver greys with no accent colour at all, so the jewellery photos stand out most. Headings use the classic Cormorant, while body text uses the compact Inter Tight, which reads easily on a phone."},"images":[{"url":"/media/seed/ciri-hp-home.webp","alt":{"id":"Beranda Ciri di HP: cincin perak di jari dengan judul Your Personal Mark dan tombol Shop Now","en":"Ciri homepage on a phone: a silver ring on a finger with the headline Your Personal Mark and a Shop Now button"},"width":600,"height":1298}]},{"title":{"id":"Koleksi dan kategori","en":"Collection and categories"},"text":{"id":"Halaman koleksi menampilkan ketiga belas perhiasan dalam satu grid. Pembeli bisa memilih kategori cincin, kalung, atau anting, menyaring menurut ketersediaan dan bentuk, lalu mengurutkan hasilnya.","en":"The collection page lays out all 13 pieces in one grid. Shoppers can pick rings, necklaces or earrings, filter by availability and form, then sort the results."},"images":[{"url":"/media/seed/ciri-katalog.webp","alt":{"id":"Halaman koleksi Ciri: pilihan kategori, filter ketersediaan dan bentuk, dan grid cincin perak","en":"Ciri collection page: category choices, availability and form filters, and a grid of silver rings"},"width":1600,"height":1000}]},{"title":{"id":"Halaman produk dan tas belanja","en":"Product pages and the bag"},"text":{"id":"Setiap perhiasan punya halaman sendiri dengan foto, detail produk, dan catatan perawatan perak. Tas belanja terbuka dari samping, jadi pembeli bisa menambah barang tanpa meninggalkan halaman.","en":"Each piece has its own page with photos, product details and silver care notes. The bag slides open from the side, so shoppers can add items without leaving the page."},"images":[{"url":"/media/seed/ciri-produk.webp","alt":{"id":"Halaman produk Hollow Ring versi desktop","en":"Hollow Ring product page on desktop"},"width":1600,"height":1000},{"url":"/media/seed/ciri-hp.webp","alt":{"id":"Halaman produk Hollow Ring versi HP","en":"Hollow Ring product page on a phone"},"width":600,"height":1298}]},{"title":{"id":"Journal dan alur belanja lengkap","en":"Journal and the full shopping flow"},"text":{"id":"Delapan artikel journal mengisi sisi editorial toko. Halaman tentang, kontak, bantuan, akun, checkout, dan konfirmasi pesanan juga dirancang, jadi klien bisa mencoba belanja dari beranda sampai pesanan selesai.","en":"Eight journal articles carry the editorial side of the store. The about, contact, help, account, checkout and order confirmation pages are designed too, so the client can try a purchase from the homepage to the final confirmation."},"images":[]}]},{"type":"flow","title":{"id":"Dari arah visual ke toko","en":"From visual direction to store"},"steps":[{"id":"Menetapkan arah visual: grafit, abu perak, tanpa aksen","en":"Set the visual direction: graphite, silver greys, no accent"},{"id":"Merancang 35 halaman dalam versi desktop dan HP","en":"Design 35 pages in desktop and phone versions"},{"id":"Menyatukannya dalam satu file preview yang bisa diklik","en":"Put them together in one clickable preview file"},{"id":"Klien mencoba alur belanja dan memberi catatan","en":"The client clicks through the shopping flow and leaves notes"},{"id":"Toko dibangun setelah desainnya disetujui","en":"The store gets built once the design is approved"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Prototipe sebelum kode","en":"Prototype before code"},"text":{"id":"Klien bisa mengklik seluruh toko sebelum satu baris kode toko ditulis. Mengubah desain di tahap ini jauh lebih murah dan cepat daripada mengubah toko yang sudah jadi.","en":"The client can click through the whole store before a single line of store code is written. Changing a design at this stage is far cheaper and quicker than changing a finished store."}},{"title":{"id":"Perak yang menjadi warnanya","en":"The silver is the colour"},"text":{"id":"Tanpa warna aksen, tombol dan tautan tidak berebut perhatian dengan produk. Satu-satunya kilau di halaman datang dari foto perak itu sendiri.","en":"With no accent colour, buttons and links don''t compete with the products for attention. The only shine on the page comes from the silver in the photos."}},{"title":{"id":"Setiap halaman punya versi HP","en":"Every page has a phone version"},"text":{"id":"Ke-35 halaman dirancang untuk desktop dan HP sekaligus, jadi klien menilai keduanya sebelum toko dibangun, bukan menemukan masalah tampilan HP setelah tayang.","en":"All 35 pages are designed for desktop and phone together, so the client judges both before the build instead of finding phone layout problems after launch."}},{"title":{"id":"Catatan perawatan di halaman produk","en":"Care notes on the product page"},"text":{"id":"Perak bisa menghitam jika salah dirawat. Catatan perawatan ditaruh di halaman produk, supaya pembeli tahu cara menjaganya sejak sebelum membeli.","en":"Silver can tarnish if it''s cared for the wrong way. Care notes sit on the product page, so shoppers know how to look after a piece before they buy it."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"13","label":{"id":"perhiasan dalam 8 bentuk","en":"pieces in 8 forms"}},{"value":"35","label":{"id":"halaman, desktop dan HP","en":"pages, desktop and phone"}},{"value":"8","label":{"id":"artikel journal","en":"journal articles"}},{"value":"0","label":{"id":"warna aksen, perak yang bicara","en":"accent colours, the silver speaks"}}],"stack":{"id":"Dibangun dengan HTML, CSS, dan JavaScript dalam satu file preview, memakai huruf Cormorant dan Inter Tight.","en":"Built with HTML, CSS and JavaScript as a single preview file, set in Cormorant and Inter Tight."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'ciri') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'website-invisual', true, '{"subtitle":{"id":"Situs portofolio dan CMS dua bahasa untuk studio desain di Bandung, dengan seluruh isi yang bisa diubah tim sendiri.","en":"A bilingual portfolio site and CMS for a Bandung design studio, with every word editable by the team."},"labels":{"client":"Invisual Studio","field":{"id":"Studio desain visual","en":"Visual design studio"},"role":{"id":"Desain, pengembangan, database, rilis","en":"Design, development, database, release"},"year":"2026"},"cover":{"url":"/media/seed/web-contact.webp","alt":{"id":"Halaman kontak Invisual Studio versi Bahasa Indonesia, mode gelap","en":"Invisual Studio contact page in Indonesian, dark mode"},"width":1600,"height":1000},"theme":{"wall":"#101011","ink":"#F2F2F2","muted":"#A6A6AC","accent":"#F65294","btnBg":"#F65294","btnInk":"#101011"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Invisual Studio adalah studio desain visual di Bandung yang mengerjakan identitas visual, ilustrasi, dan kemasan. Situsnya harus menampilkan karya, mendatangkan calon klien lewat pencarian Google, dan bisa diurus tim yang bukan programmer, dalam bahasa Indonesia dan Inggris.","en":"Invisual Studio is a visual design studio in Bandung working on visual identity, illustration and packaging. Its site has to show the work, bring in prospective clients through Google search, and be run by a team of non-programmers, in Indonesian and English."},{"id":"Saya mengirim pembaruannya bertahap, lebih dari 20 paket, sebagian besar disertai catatan berbahasa sederhana untuk pemilik studio. Salah satu paket berisi audit keamanan yang saya jalankan sendiri, termasuk memperbarui framework situs untuk menutup sebuah celah keamanan.","en":"I shipped the updates in stages, more than 20 packages, most with plain-language notes for the studio owner. One package was a security audit I ran myself, which included updating the site''s framework to close a security hole."}]},{"type":"features","title":{"id":"Situs publik dan panel tim","en":"The public site and the team''s panel"},"items":[{"title":{"id":"Brief proyek satu pertanyaan per layar","en":"A one-question-per-screen project brief"},"text":{"id":"Calon klien mengisi brief proyek seperti sedang mengobrol: tujuh pertanyaan, satu per layar, termasuk kisaran budget, dalam bahasa Indonesia atau Inggris. Brief yang masuk langsung tersimpan di kotak masuk admin.","en":"Prospective clients fill in the brief as if they''re having a conversation: seven questions, one per screen, including a budget range, in Indonesian or English. Each brief lands straight in the admin inbox."},"images":[{"url":"/media/seed/web-brief.webp","alt":{"id":"Form Start a Project, langkah 5 dari 7: pilihan kisaran budget","en":"Start a Project form, step 5 of 7: choosing a budget range"},"width":1440,"height":1300}]},{"title":{"id":"Karya, blog, dan halaman studio","en":"Work, blog and studio pages"},"text":{"id":"Karya bisa disaring menurut lingkup dan industri, masing-masing dengan halaman studi kasus. Artikel blog menampilkan waktu baca dan artikel terkait, dan halaman tentang memuat layanan, tim, dan testimoni.","en":"Work can be filtered by scope and industry, each piece with its own case study. Blog posts show reading time and related articles, and the about page covers services, the team and testimonials."},"images":[]},{"title":{"id":"Semua isi bisa diubah sendiri","en":"Every word is editable"},"text":{"id":"Tim mengubah karya, klien, testimoni, tim, layanan, FAQ, dan kontak dari panel admin, dalam bahasa Indonesia dan Inggris. Kedua bahasa memakai alamat halaman yang sama, dan pengunjung tinggal menekan tombol EN atau ID.","en":"The team edits work, clients, testimonials, team, services, FAQ and contact details from the admin panel, in Indonesian and English. Both languages share the same page address, and visitors just tap EN or ID."},"images":[{"url":"/media/seed/web-hp.webp","alt":{"id":"Halaman kontak Invisual Studio di HP, dengan tombol pilihan bahasa EN dan ID","en":"Invisual Studio contact page on a phone, with the EN and ID language switch"},"width":600,"height":1298}]},{"title":{"id":"Editor blog yang memeriksa SEO","en":"A blog editor that checks SEO"},"text":{"id":"Sebelum artikel terbit, editor memeriksa 14 poin SEO dan memperbaiki sebagian dengan satu klik. Penulis bisa melihat pratinjau tampilan di Google dan media sosial, menjadwalkan terbit dalam WIB, dan tulisannya tersimpan otomatis.","en":"Before a post goes live, the editor checks 14 SEO points and fixes some of them in one click. Writers can preview how it looks on Google and social media, schedule it in Jakarta time, and their work saves automatically."},"images":[]}]},{"type":"flow","title":{"id":"Dari pencarian ke brief","en":"From search to brief"},"steps":[{"id":"Calon klien menemukan artikel blog lewat Google","en":"A prospective client finds a blog post through Google"},{"id":"Membuka karya dan studi kasus yang relevan","en":"They browse relevant work and case studies"},{"id":"Mengisi brief proyek satu pertanyaan per layar","en":"They fill in the one-question-per-screen brief"},{"id":"Brief masuk ke kotak masuk dan bisa ditandai penting","en":"The brief lands in the inbox, where it can be flagged as important"},{"id":"Statistik menunjukkan dari mana pengunjung datang","en":"Visitor stats show where people came from"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Mesin pencari langsung diberi tahu","en":"Search engines hear about new posts right away"},"text":{"id":"Saat artikel atau karya terbit, situs langsung memberi tahu Google dan mesin pencari lain, tanpa menunggu dirayapi. Artikel juga bisa dijadwalkan terbit di jam tertentu.","en":"When a post or project goes live, the site notifies Google and other search engines straight away instead of waiting to be crawled. Posts can also be scheduled for a set time."}},{"title":{"id":"Form dan login terlindungi dari spam","en":"Forms and login are guarded against spam"},"text":{"id":"Form kontak punya jebakan tersembunyi untuk bot, dan jumlah percobaan kirim serta login dibatasi. Login admin yang gagal berkali-kali akan tertahan sementara.","en":"Contact forms carry hidden traps for bots, and the number of submissions and login attempts is limited. Repeated failed admin logins are put on hold for a while."}},{"title":{"id":"Pelacakan iklan menunggu izin","en":"Ad tracking waits for consent"},"text":{"id":"Pixel iklan Meta baru aktif setelah pengunjung menyetujuinya. Statistik pengunjung milik studio sendiri dikelompokkan menurut waktu Jakarta, jadi angka harian mengikuti hari kalender di Indonesia.","en":"Meta''s ad pixel only switches on after the visitor agrees. The studio''s own visitor stats are grouped by Jakarta time, so daily numbers follow the Indonesian calendar day."}},{"title":{"id":"Cadangan data bisa diunduh pemilik","en":"The owner can download backups"},"text":{"id":"Pemilik bisa mengunduh cadangan isi situs dalam file JSON atau CSV. File CSV-nya aman dibuka di Excel, karena isian yang menyerupai rumus tidak ikut dijalankan.","en":"The owner can download a backup of the site''s content as JSON or CSV. The CSV files are safe to open in Excel, because entries that look like formulas won''t run."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"22","label":{"id":"halaman: 8 publik, 14 admin","en":"pages: 8 public, 14 admin"}},{"value":"14","label":{"id":"poin SEO dicek sebelum terbit","en":"SEO checks before publishing"}},{"value":"2","label":{"id":"bahasa, satu alamat","en":"languages, one address"}},{"value":"20+","label":{"id":"paket pembaruan dikirim","en":"update packages shipped"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Tailwind CSS, Supabase (PostgreSQL), Cloudinary, Resend, Vercel.","en":"Built with Next.js, React, TypeScript, Tailwind CSS, Supabase (PostgreSQL), Cloudinary, Resend, Vercel."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'website-invisual') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'internet-bandung', true, '{"subtitle":{"id":"Situs penjualan internet rumah di Bandung yang mengarahkan setiap pengunjung ke WhatsApp.","en":"A home internet sales site in Bandung that sends every visitor to WhatsApp."},"labels":{"client":"Internet Bandung","field":{"id":"Penjualan internet rumah","en":"Home internet sales"},"role":{"id":"Desain, pengembangan, database, rilis","en":"Design, development, database, release"},"year":"2026"},"cover":{"url":"/media/seed/intbdg-paket.webp","alt":{"id":"Pilihan paket internet rumah dengan tab durasi 1, 6, dan 12 bulan","en":"Home internet plans with 1, 6 and 12-month tabs"},"width":1600,"height":1000},"theme":{"wall":"#FFF5F9","ink":"#26202E","muted":"#5C5566","accent":"#D8006F","btnBg":"#D8006F","btnInk":"#FFFFFF"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Internet Bandung menjual paket internet rumah, fiber dan 5G, untuk wilayah Bandung. Calon pelanggan biasanya ingin bertanya dulu soal jangkauan dan harga sebelum berlangganan, dan percakapan itu terjadi di WhatsApp.","en":"Internet Bandung sells fibre and 5G home internet plans around Bandung. Prospective customers usually want to ask about coverage and price before they subscribe, and that conversation happens on WhatsApp."},{"id":"Jadi situsnya punya satu tugas: membawa pengunjung ke WhatsApp, lalu memberi tahu pemilik tombol mana yang paling banyak menghasilkan percakapan. Harga, promo, dan kota jangkauan juga harus bisa diubah pemilik sendiri, tanpa developer.","en":"So the site has one job: get visitors onto WhatsApp, then tell the owner which buttons start the most conversations. The owner also needs to change prices, promos and coverage cities without a developer."}]},{"type":"features","title":{"id":"Halaman jualan dan panel pemilik","en":"The sales page and the owner''s panel"},"items":[{"title":{"id":"Paket dan harga","en":"Plans and prices"},"text":{"id":"Paket tampil dengan tab durasi 1, 6, dan 12 bulan, lengkap dengan harga coret. Setiap tombol paket membuka WhatsApp, dan kliknya tercatat per paket.","en":"Plans come with 1, 6 and 12-month tabs and struck-through original prices. Every plan button opens WhatsApp, and clicks are logged per plan."},"images":[{"url":"/media/seed/intbdg-hp.webp","alt":{"id":"Paket internet di HP dengan tombol WhatsApp","en":"Internet plans on a phone with a WhatsApp button"},"width":600,"height":1298}]},{"title":{"id":"Cek jangkauan dan pendaftaran","en":"Coverage check and sign-up"},"text":{"id":"Pengunjung mencari kotanya di daftar jangkauan, lalu mengisi form singkat: nama, nomor WhatsApp, alamat, kota, dan paket yang diminati. Datanya tersimpan sebagai calon pelanggan, kemudian WhatsApp terbuka dengan pesan yang sudah terisi.","en":"Visitors look up their city in the coverage list, then fill in a short form: name, WhatsApp number, address, city and the plan they want. Their details are saved as a lead, and WhatsApp opens with the message already written."},"images":[{"url":"/media/seed/intbdg-form.webp","alt":{"id":"Pop-up Cek coverage dan daftar: nama, nomor WhatsApp, alamat, kota, paket, dan tombol lanjut ke WhatsApp","en":"Coverage check and sign-up pop-up: name, WhatsApp number, address, city, plan and a button that continues to WhatsApp"},"width":1600,"height":1000}]},{"title":{"id":"Panel admin tanpa kode","en":"A no-code admin panel"},"text":{"id":"Delapan panel untuk mengubah slide hero, paket dan harga, isi halaman, kota jangkauan, footer, nomor WhatsApp, promo, jam layanan, dan SEO. Perubahan langsung tampil di layar pengunjung yang sedang membuka situs, tanpa perlu dimuat ulang.","en":"Eight panels cover the hero slides, plans and prices, page content, coverage cities, footer, WhatsApp number, promos, opening hours and SEO. Changes appear on the screens of visitors already on the site, with no reload needed."},"images":[]},{"title":{"id":"Ringkasan dan daftar pendaftar","en":"Summary and sign-up list"},"text":{"id":"Pemilik melihat kunjungan, klik WhatsApp, dan pendaftar per hari, untuk hari ini, 7, 30, atau 90 hari terakhir, atau rentang tanggal sendiri. Setiap pendaftar punya tombol untuk langsung menghubunginya lewat WhatsApp.","en":"The owner sees visits, WhatsApp clicks and sign-ups per day, for today, the last 7, 30 or 90 days, or a custom date range. Each sign-up has a button to contact them on WhatsApp directly."},"images":[{"url":"/media/seed/intbdg-admin.webp","alt":{"id":"Dasbor admin: kunjungan, klik WhatsApp, pendaftar, paket aktif, kota jangkauan, dan grafik tren harian","en":"Admin dashboard: visits, WhatsApp clicks, sign-ups, active plans, coverage cities and a daily trend chart"},"width":1280,"height":789}]}]},{"type":"flow","title":{"id":"Dari kunjungan ke percakapan","en":"From visit to conversation"},"steps":[{"id":"Pengunjung datang dan melihat promo di bagian atas","en":"A visitor arrives and sees the promo at the top"},{"id":"Memilih durasi paket dan membandingkan harga","en":"They pick a plan length and compare prices"},{"id":"Mengecek apakah kotanya sudah terjangkau","en":"They check whether their city is covered"},{"id":"Mengisi form atau langsung menekan tombol WhatsApp","en":"They fill in the form or tap a WhatsApp button"},{"id":"Pemilik melanjutkan percakapan dan melihat tombol mana yang berhasil","en":"The owner picks up the chat and sees which button worked"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"WhatsApp tetap terbuka walau penyimpanan gagal","en":"WhatsApp opens even if saving fails"},"text":{"id":"Jika data pendaftar gagal tersimpan karena gangguan, WhatsApp tetap terbuka dengan pesan yang sudah terisi. Calon pelanggan tidak hilang hanya karena masalah teknis.","en":"If a sign-up fails to save because of a glitch, WhatsApp still opens with the message filled in. A technical hiccup doesn''t cost a lead."}},{"title":{"id":"Setiap klik tahu asalnya","en":"Every click knows where it came from"},"text":{"id":"Klik WhatsApp dicatat menurut tombolnya: menu atas, kartu paket, tombol melayang, atau form. Data yang sama dikirim ke Google Analytics dan Meta Pixel untuk mengukur iklan.","en":"WhatsApp clicks are logged by button: top menu, plan card, floating button or form. The same data goes to Google Analytics and Meta Pixel to measure ads."}},{"title":{"id":"Angka di dasbor adalah angka asli","en":"The dashboard shows real numbers"},"text":{"id":"Versi awal dasbor masih memakai angka contoh. Pada 14 Oktober, angka itu diganti data kunjungan dan klik yang sebenarnya, dan dasbor ikut diperbarui setiap ada aktivitas baru di situs.","en":"The first version of the dashboard used sample numbers. On 14 October they were replaced with real visit and click data, and the dashboard now updates whenever there''s new activity on the site."}},{"title":{"id":"Siap dibaca mesin pencari","en":"Ready for search engines"},"text":{"id":"Judul, deskripsi, dan gambar pratinjau media sosial diatur dari admin. Setiap paket juga ditandai sebagai penawaran harga yang bisa dibaca Google.","en":"The title, description and social preview image are set from the admin. Each plan is also marked up as a priced offer that Google can read."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"8","label":{"id":"panel admin tanpa kode","en":"no-code admin panels"}},{"value":"3","label":{"id":"pilihan durasi paket: 1, 6, 12 bulan","en":"plan lengths: 1, 6 or 12 months"}},{"value":"4","label":{"id":"jenis tombol WhatsApp yang dilacak","en":"kinds of WhatsApp button tracked"}},{"value":"1","label":{"id":"tujuan untuk setiap tombol: WhatsApp","en":"destination for every button: WhatsApp"}}],"stack":{"id":"Dibangun dengan Next.js, React, TypeScript, Supabase (PostgreSQL), Google Analytics 4, Meta Pixel, Vercel.","en":"Built with Next.js, React, TypeScript, Supabase (PostgreSQL), Google Analytics 4, Meta Pixel, Vercel."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'internet-bandung') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'point-pos', true, '{"subtitle":{"id":"Prototipe kasir coffee shop yang memotong stok bahan baku di setiap penjualan.","en":"A coffee-shop point-of-sale prototype that deducts ingredients with every sale."},"labels":{"client":"POINT","field":{"id":"Coffee shop","en":"Coffee shops"},"role":{"id":"Desain produk, prototipe interaktif","en":"Product design, interactive prototype"},"year":"2026"},"cover":{"url":"/media/seed/point-kasir.webp","alt":{"id":"Layar kasir POINT: menu kopi, pesanan berisi varian dan add-on, pajak PB1, dan pilihan bayar","en":"POINT till screen: coffee menu, an order with variants and add-ons, PB1 tax and payment options"},"width":1600,"height":1000},"theme":{"wall":"#FBF8F2","ink":"#2B2620","muted":"#6B6355","accent":"#2F6BFF","btnBg":"#2B2620","btnInk":"#FBF8F2"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Di coffee shop, satu gelas memakai beberapa bahan sekaligus: biji kopi, susu UHT, gula aren, sirup, mint, dan cup. Kasir yang hanya mencatat gelas terjual tidak bisa memberi tahu kapan bahan akan habis, berapa modal setiap menu, atau berapa margin yang tersisa.","en":"In a coffee shop, one drink uses several ingredients at once: coffee beans, UHT milk, palm sugar, syrup, mint and the cup itself. A till that only counts cups sold can''t tell you when ingredients will run out, what each item costs to make, or how much margin is left."},{"id":"POINT POS adalah prototipe interaktif untuk menjawab itu: kasir, layar barista, dashboard, riwayat, inventori, dan stock opname dalam satu aplikasi. Prototipe ini belum dipakai di toko sungguhan, tapi setiap alurnya bisa langsung dicoba di browser.","en":"POINT POS is an interactive prototype built to answer that: till, barista screen, dashboard, history, inventory and stock counts in one app. It isn''t running in a real shop yet, but every flow can be tried right in the browser."}]},{"type":"features","title":{"id":"Enam modul, satu kasir","en":"Six modules, one till"},"items":[{"title":{"id":"Kasir dengan lembar opsi","en":"A till with an option sheet"},"text":{"id":"Setiap menu membuka lembar opsi: ukuran Regular atau Large (+Rp 6.000), panas atau dingin, extra shot (+Rp 5.000), extra syrup (+Rp 3.000), dan catatan. Pembayaran bisa tunai, QRIS, kartu, atau e-wallet, dengan numpad dan tombol uang pas untuk tunai.","en":"Each item opens an option sheet: Regular or Large (+Rp 6,000), hot or iced, extra shot (+Rp 5,000), extra syrup (+Rp 3,000) and notes. Customers pay by cash, QRIS, card or e-wallet, with a numpad and exact-amount buttons for cash."},"images":[{"url":"/media/seed/point-opsi.webp","alt":{"id":"Lembar opsi Caramel Macchiato: ukuran, suhu, add-on, dan catatan","en":"Caramel Macchiato option sheet: size, temperature, add-ons and notes"},"width":1600,"height":1000},{"url":"/media/seed/point-hp.webp","alt":{"id":"Katalog menu POINT di HP dengan harga dan SKU setiap menu","en":"POINT menu catalogue on a phone with each item''s price and SKU"},"width":600,"height":1298}]},{"title":{"id":"Layar barista","en":"Barista screen"},"text":{"id":"Pesanan dari kasir langsung masuk ke layar barista, lengkap dengan keterangan dine-in atau takeaway. Barista menekan mulai buat, lalu tandai selesai, jadi antrean di bar selalu jelas.","en":"Orders from the till go straight to the barista screen, marked dine-in or takeaway. Baristas tap start, then done, so the queue at the bar is always clear."},"images":[{"url":"/media/seed/point-barista.webp","alt":{"id":"Layar barista dengan dua pesanan: satu sedang diproses, satu baru masuk","en":"Barista screen with two orders: one in progress, one just in"},"width":1600,"height":1000}]},{"title":{"id":"Resep dan inventori","en":"Recipes and inventory"},"text":{"id":"Setiap menu punya resep bahan, jadi penjualan langsung mengurangi stok biji kopi, susu, gula aren, sirup, mint, dan cup. SKU dibuat otomatis, misalnya BEV-CML-001, dan HPP serta margin per menu terhitung sendiri.","en":"Every item has a recipe, so each sale deducts coffee beans, milk, palm sugar, syrup, mint and cups from stock. SKUs are generated automatically, like BEV-CML-001, and cost of goods and margin per item calculate themselves."},"images":[{"url":"/media/seed/point-inventori.webp","alt":{"id":"Tabel inventori menu dengan SKU, harga, HPP, margin, stok, dan status","en":"Menu inventory table with SKU, price, cost of goods, margin, stock and status"},"width":1600,"height":1000}]},{"title":{"id":"Dashboard, riwayat, dan stock opname","en":"Dashboard, history and stock counts"},"text":{"id":"Dashboard menampilkan penjualan dan transaksi hari ini, menu terlaris, stok menipis, dan penjualan per jam. Riwayat menyimpan setiap transaksi, dan stock opname berjalan per sesi dengan catatan selisih.","en":"The dashboard shows today''s sales and transactions, the best seller, low stock and sales per hour. History keeps every transaction, and stock counts run in sessions with a log of differences."},"images":[{"url":"/media/seed/point-dashboard.webp","alt":{"id":"Dashboard hari ini: penjualan, transaksi, menu terlaris, stok menipis, dan grafik penjualan per jam","en":"Today''s dashboard: sales, transactions, best seller, low stock and an hourly sales chart"},"width":1600,"height":1000},{"url":"/media/seed/point-opname.webp","alt":{"id":"Stock opname: mulai sesi baru, sakelar blind count, dan riwayat sesi dengan jumlah selisih","en":"Stock count: starting a new session, the blind count toggle and a session history with differences"},"width":1600,"height":1000}]}]},{"type":"flow","title":{"id":"Satu pesanan, dari kasir ke gudang","en":"One order, from till to storeroom"},"steps":[{"id":"Kasir memilih menu, lalu mengatur ukuran, suhu, dan add-on","en":"The cashier picks an item and sets size, temperature and add-ons"},{"id":"Sistem mengecek bahan dan menambahkan pajak PB1 11%","en":"The system checks ingredients and adds 11% PB1 tax"},{"id":"Pelanggan membayar tunai, QRIS, kartu, atau e-wallet","en":"The customer pays by cash, QRIS, card or e-wallet"},{"id":"Stok bahan terpotong sesuai resep","en":"Ingredients come off stock according to the recipe"},{"id":"Pesanan masuk ke layar barista sampai ditandai selesai","en":"The order goes to the barista screen until it''s marked done"},{"id":"Stock opname mencocokkan stok sistem dengan hitungan fisik","en":"A stock count checks system stock against what''s on the shelf"}]},{"type":"decisions","title":{"id":"Keputusan yang melindungi bisnis","en":"Decisions that protect the business"},"items":[{"title":{"id":"Penjualan ditahan saat bahan habis","en":"Sales stop when ingredients run out"},"text":{"id":"Jika bahan untuk satu menu tidak cukup, kasir tidak bisa menjualnya dan muncul pesan “Bahan tidak cukup”. Tidak ada pesanan yang terlanjur dibayar lalu ternyata tidak bisa dibuat.","en":"If there aren''t enough ingredients for an item, the till won''t sell it and shows “Bahan tidak cukup” (not enough ingredients). No order gets paid for and then turns out impossible to make."}},{"title":{"id":"Blind count untuk stock opname","en":"Blind counts for stock takes"},"text":{"id":"Saat menghitung, stok menurut sistem disembunyikan dan dibekukan, jadi petugas mencatat yang benar-benar ada di rak, bukan menyalin angka di layar. Selisihnya baru terlihat setelah hitungan selesai.","en":"During a count, the system''s stock figure is hidden and frozen, so staff record what''s actually on the shelf instead of copying the number on screen. Differences only show once the count is done."}},{"title":{"id":"Modal dan margin selalu terlihat","en":"Cost and margin always in view"},"text":{"id":"Karena setiap menu punya resep, HPP dan margin terhitung per item. Pemilik bisa melihat menu mana yang laris tapi untungnya tipis, lalu menyesuaikan harga atau resepnya.","en":"Because every item has a recipe, cost of goods and margin are worked out per item. The owner can spot what sells well but earns little, then adjust the price or the recipe."}},{"title":{"id":"Tambahan kecil tidak lupa ditagih","en":"Small extras always get charged"},"text":{"id":"Ukuran Large, extra shot, dan extra syrup langsung menambah harga di pesanan, dan pajak PB1 11% dihitung otomatis. Kasir tidak perlu menghitung tambahan di kepala.","en":"Large sizes, extra shots and extra syrup add to the order price straight away, and the 11% PB1 tax is calculated automatically. The cashier never has to add up extras in their head."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"6","label":{"id":"modul dalam satu aplikasi","en":"modules in one app"}},{"value":"4","label":{"id":"cara bayar: tunai, QRIS, kartu, e-wallet","en":"ways to pay: cash, QRIS, card, e-wallet"}},{"value":"11%","label":{"id":"pajak PB1 dihitung otomatis","en":"PB1 tax calculated automatically"}},{"value":"1","label":{"id":"resep per menu, stok terpotong sendiri","en":"recipe per item, stock deducts itself"}}],"stack":{"id":"Dibangun sebagai prototipe interaktif dengan HTML, CSS, dan JavaScript, langsung berjalan di browser.","en":"Built as an interactive prototype in HTML, CSS and JavaScript that runs right in the browser."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'point-pos') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'vale', true, '{"subtitle":{"id":"Situs golf clubhouse yang menjadikan setiap pegolf seorang ksatria: peta kerajaan, enam bab, dan pemesanan tee time.","en":"A golf clubhouse site where every golfer becomes a knight: a map of the realm, six chapters and tee-time booking."},"labels":{"client":"VALE Golf Clubhouse","field":{"id":"Golf clubhouse","en":"Golf clubhouse"},"role":{"id":"Desain situs, interaksi, dan front-end, bersama Invisual Studio","en":"Site design, interaction and front-end, with Invisual Studio"},"year":"2026"},"cover":{"url":"/media/seed/vale-peta.webp","alt":{"id":"Beranda VALE: peta kerajaan bergaya cetak dengan enam landmark, kompas, dan daftar Legend of the Realm","en":"VALE homepage: a printed-style map of the realm with six landmarks, a compass and the Legend of the Realm list"},"width":1600,"height":1000},"theme":{"wall":"#FBEBD6","ink":"#3E2A24","muted":"#6B4A3F","accent":"#817916","btnBg":"#5B3C34","btnInk":"#FED7AB"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"VALE adalah destinasi golf modern yang terinspirasi semangat ksatria abad pertengahan: setiap pegolf menjadi ksatria, setiap fairway menjadi kerajaan, dan setiap ronde menjadi petualangan. Situsnya harus membawa cerita itu sampai terasa, tanpa membuat pengunjung tersesat saat ingin memesan tee time.","en":"VALE is a modern golf destination inspired by the spirit of medieval knights: every golfer becomes a knight, every fairway a realm and every round a quest. The site had to carry that story until you could feel it, without losing visitors who just want to book a tee time."},{"id":"Proyek ini dikerjakan di Invisual Studio. Hasilnya satu file preview berisi peta kerajaan dan enam bab, lengkap di desktop dan HP, yang berjalan tanpa server. Situsnya belum tayang, dan formulir di dalamnya tidak mengirim apa pun.","en":"The project was made at Invisual Studio. The result is a single preview file holding the realm map and six chapters, complete on desktop and phone, that runs without a server. The site isn''t live yet, and its forms send nothing."}]},{"type":"features","title":{"id":"Negeri yang bisa dikelilingi","en":"A realm you can explore"},"items":[{"title":{"id":"Peta negeri","en":"The map of the realm"},"text":{"id":"Beranda adalah peta lapangan yang bisa digeser dan diperbesar. Enam landmark, dari Training Ground sampai King''s Reach, membuka kartu cerita masing-masing dan menuju babnya. Setiap landmark yang dibuka memberi satu segel di Quest Log.","en":"The homepage is a map of the course you can drag and zoom. Six landmarks, from the Training Ground to the King''s Reach, each open a story card that leads into its chapter. Every landmark you open stamps a seal in the Quest Log."},"images":[{"url":"/media/seed/vale-kartu.webp","alt":{"id":"Peta dengan kartu landmark The Great Hall terbuka di sisi kanan","en":"The map with The Great Hall landmark card open on the right"},"width":1600,"height":1000},{"url":"/media/seed/vale-hp-peta.webp","alt":{"id":"Kartu landmark The Great Hall di HP","en":"The Great Hall landmark card on phone"},"width":600,"height":1298}]},{"title":{"id":"Enam bab, satu buku","en":"Six chapters, one book"},"text":{"id":"The Legend, The Course, The Great Hall, The Knights Cup, The Order, dan Begin the Quest dibaca seperti buku: berpindah bab terasa seperti membalik halaman, dan The Chronicle menjadi daftar isinya. Di The Legend, Green Knight berganti pose sambil digulir dan enam companion bisa dibalik seperti medali.","en":"The Legend, The Course, The Great Hall, The Knights Cup, The Order and Begin the Quest read like a book: moving between chapters feels like turning a page, and The Chronicle is the table of contents. In The Legend, the Green Knight changes pose as you scroll and six companions turn over like medallions."},"images":[{"url":"/media/seed/vale-legenda.webp","alt":{"id":"Enam companion dalam bingkai oval, dua di antaranya sudah dibalik dan menampilkan ceritanya","en":"Six companions in oval frames, two of them turned over to show their story"},"width":1600,"height":1000}]},{"title":{"id":"Lapangan dalam detail","en":"The course in detail"},"text":{"id":"Bab The Course memperkenalkan kontur lapangan, lima bendera dengan angka dan kata, dan hole VII The Dragon''s Bunker lengkap dengan par dan jarak dari setiap tee. Kode ksatria ditutup dengan tiga aturan sederhana di lapangan.","en":"The Course chapter introduces the contours, five flags each with a numeral and a word, and hole VII, The Dragon''s Bunker, with its par and the distance from every tee. The knight''s code closes it with three simple rules on the green."},"images":[{"url":"/media/seed/vale-hole.webp","alt":{"id":"Hole VII The Dragon''s Bunker: par 4, jarak tiga tee, dan foto batu penanda","en":"Hole VII, The Dragon''s Bunker: par 4, three tee distances and photos of the marker stone"},"width":1600,"height":1000}]},{"title":{"id":"Great Hall dan Armoury","en":"The Great Hall and the Armoury"},"text":{"id":"Clubhouse tampil lewat foto ruangannya, papan pengumuman yang posternya bisa digeser, dan rak Armoury berisi delapan barang yang bisa ditarik untuk dijelajahi.","en":"The clubhouse comes through its room photographs, a notice board whose posters you can drag about, and an Armoury rack of eight goods you pull to browse."},"images":[{"url":"/media/seed/vale-armoury.webp","alt":{"id":"New Goods from the Armoury: polo, topi, kaus kaki, dan sweater dalam rak yang bisa digeser","en":"New Goods from the Armoury: a polo, cap, socks and sweater on a rack you can drag"},"width":1600,"height":1000}]},{"title":{"id":"Kartu anggota The Order","en":"The Order''s member card"},"text":{"id":"Pengunjung menulis namanya dan langsung melihatnya di kartu anggota, lengkap dengan nomor anggota. Kartunya miring mengikuti kursor dan bisa dibalik. Di bawahnya ada empat hak anggota dan formulir untuk meminta undangan.","en":"Visitors write their name and see it on the member card straight away, with a member number. The card tilts with the cursor and turns over. Below are the four privileges of the Order and a form to request an invitation."},"images":[{"url":"/media/seed/vale-order.webp","alt":{"id":"Kartu anggota VALE bertuliskan Sir Galahad, di samping teks A true member of the Vale","en":"A VALE member card reading Sir Galahad, beside the line A true member of the Vale"},"width":1600,"height":1000}]},{"title":{"id":"Pesan tee time","en":"Booking a tee time"},"text":{"id":"Begin the Quest memandu pemesanan dalam enam langkah, dari tanggal sampai data diri. Tiket di sampingnya terisi sambil pengunjung memilih, dan jam pagi ditandai Early Knight. Di HP, ringkasannya menempel sebagai bilah di bawah layar.","en":"Begin the Quest walks through the booking in six steps, from the date to the player''s details. The ticket beside it fills in as the visitor chooses, and dawn slots are marked Early Knight. On phones the summary sits in a bar at the bottom of the screen."},"images":[{"url":"/media/seed/vale-quest.webp","alt":{"id":"Formulir tee time: tanggal, jam 7:00 bertanda Early Knight, dan tiket VALE yang sudah terisi","en":"The tee-time form: a date, the 7:00 slot marked Early Knight, and the filled VALE ticket"},"width":1600,"height":1000},{"url":"/media/seed/vale-hp-quest.webp","alt":{"id":"Segel lilin dan pesan Your quest begins setelah booking di HP","en":"A wax seal and the message Your quest begins after booking on phone"},"width":600,"height":1298}]}]},{"type":"flow","title":{"id":"Alur memesan tee time","en":"Booking a tee time"},"steps":[{"id":"Pilih tanggal dari empat belas hari ke depan","en":"Pick a date from the next fourteen days"},{"id":"Pilih jam; jam pagi bertanda Early Knight","en":"Choose a time; dawn slots are marked Early Knight"},{"id":"Atur jumlah ksatria, satu sampai empat","en":"Set the party, one to four knights"},{"id":"Pilih sembilan atau delapan belas hole","en":"Choose nine or eighteen holes"},{"id":"Tambah caddie atau cart bila perlu","en":"Add a caddie or a cart if needed"},{"id":"Isi nama dan email, lalu segel booking","en":"Enter a name and email, then seal the booking"}]},{"type":"decisions","title":{"id":"Keputusan desain","en":"Design decisions"},"items":[{"title":{"id":"Terasa tercetak, bukan datar","en":"Printed, not flat"},"text":{"id":"Judul dan ilustrasinya punya tekstur tinta seperti hasil cetak buku tua. Teksturnya dibuat dengan filter SVG ringan, bukan gambar besar, jadi tetap tajam di layar mana pun.","en":"Headings and illustrations carry an ink texture like an old printed book. The texture comes from a light SVG filter rather than large images, so it stays sharp on any screen."}},{"title":{"id":"Peta yang bisa dimainkan","en":"A map you can play"},"text":{"id":"Quest Log mengumpulkan segel setiap landmark yang dibuka. Progresnya disimpan di perangkat pengunjung, dan situs tetap berjalan normal bila penyimpanan itu diblokir browser.","en":"The Quest Log collects a seal for every landmark opened. Progress is kept on the visitor''s device, and the site keeps working normally when the browser blocks that storage."}},{"title":{"id":"Cerita tidak menghalangi booking","en":"The story never blocks the booking"},"text":{"id":"Tombol Begin the Quest selalu ada di header dan di peta, dan ringkasan booking terus terlihat. Pengunjung yang hanya ingin memesan bisa langsung memesan.","en":"The Begin the Quest button is always in the header and on the map, and the booking summary stays in view. Visitors who only want to book can book straight away."}},{"title":{"id":"Tenang bila diminta","en":"Calm when asked"},"text":{"id":"Bila pengunjung memilih gerak dikurangi, animasinya ikut berhenti. Dialog, kartu, dan formulirnya memakai tombol dan label asli, jadi bisa dipakai dengan keyboard dan pembaca layar.","en":"When visitors ask for reduced motion, the animation stops. Dialogs, cards and forms use real buttons and labels, so they work with a keyboard and a screen reader."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"7","label":{"id":"halaman: peta dan enam bab","en":"pages: the map and six chapters"}},{"value":"6","label":{"id":"landmark dan enam companion","en":"landmarks and six companions"}},{"value":"50","label":{"id":"gambar vektor dalam satu file","en":"vector drawings in one file"}},{"value":"20","label":{"id":"pilihan jam tee time per hari","en":"tee times to choose from each day"}}],"stack":{"id":"Dibuat dengan HTML, CSS, dan JavaScript, GSAP (ScrollTrigger, Draggable, SplitText), Lenis, dan ilustrasi SVG. Satu file, berjalan tanpa server.","en":"Built with HTML, CSS and JavaScript, GSAP (ScrollTrigger, Draggable, SplitText), Lenis and SVG illustration. One file that runs without a server."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'vale') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'loma', true, '{"subtitle":{"id":"Situs restoran Amerika Latin di Lima: tenang tapi berani, dengan carta, kisah merek, dan reservasi meja.","en":"A Latin American restaurant site for Lima: quiet but bold, with the carta, the brand story and table reservations."},"labels":{"client":"Loma","field":{"id":"Restoran","en":"Restaurant"},"role":{"id":"Desain situs, interaksi, dan front-end, bersama Invisual Studio","en":"Site design, interaction and front-end, with Invisual Studio"},"year":"2026"},"cover":{"url":"/media/seed/loma-hero.webp","alt":{"id":"Beranda Loma: lampu dinding hangat di ruang makan gelap, wordmark Loma besar di bawah","en":"Loma homepage: a warm wall lamp in a dark dining room, the large Loma wordmark below"},"width":1600,"height":1000},"theme":{"wall":"#EEEAE3","ink":"#161513","muted":"#5C5546","accent":"#865F46","btnBg":"#161513","btnInk":"#EEEAE3"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"Loma adalah ruang makan Amerika Latin kontemporer di Lima, Peru: berakar pada tanah, dibentuk oleh api, dibuat untuk dibagi. Situsnya perlu terasa seperti ruangannya, gelap, hangat, dan pelan, sambil tetap membuat dua hal mudah: melihat carta dan memesan meja.","en":"Loma is a contemporary Latin American dining room in Lima, Peru: rooted in the land, shaped by fire, made to share. The site had to feel like the room, dark, warm and unhurried, while keeping two things easy: reading the carta and booking a table."},{"id":"Proyek ini dikerjakan di Invisual Studio sebagai satu file preview berisi empat halaman, lengkap di desktop dan HP. Situsnya belum tayang, dan formulir reservasinya tidak mengirim apa pun.","en":"The project was made at Invisual Studio as a single preview file with four pages, complete on desktop and phone. The site isn''t live yet, and its reservation form sends nothing."}]},{"type":"features","title":{"id":"Empat halaman, satu suasana","en":"Four pages, one mood"},"items":[{"title":{"id":"Tierra, Fuego, Tiempo","en":"Tierra, Fuego, Tiempo"},"text":{"id":"Beranda bercerita lewat tiga unsur, tanah, api, dan waktu, yang bergeser ke samping saat digulir. Fotonya melengkung halus mengikuti gerak gulir, dan tetap tampil sebagai foto biasa bila browser tidak mendukung WebGL.","en":"The homepage tells its story through three elements, land, fire and time, which slide sideways as you scroll. The photographs bend gently with the scroll, and still show as ordinary photos when the browser has no WebGL."},"images":[{"url":"/media/seed/loma-bab.webp","alt":{"id":"Bab Fuego di beranda: koki menuang saus di atas piring, kata FUEGO besar di bawah","en":"The Fuego chapter on the homepage: a chef pouring sauce over a plate, the word FUEGO large below"},"width":1600,"height":1000}]},{"title":{"id":"Tujuh signature","en":"Seven signatures"},"text":{"id":"Tujuh menu signature tersusun sebagai daftar. Di desktop, foto piringnya berganti saat nama menu disorot; di HP, setiap menu tampil dengan fotonya sendiri.","en":"The seven signature plates sit in a list. On desktop, the photo changes as you point at each name; on phones, every plate shows with its own photo."},"images":[{"url":"/media/seed/loma-signature.webp","alt":{"id":"Daftar signature dengan Grilled Octopus disorot dan fotonya di sebelah kanan","en":"The signature list with Grilled Octopus highlighted and its photo on the right"},"width":1600,"height":1000},{"url":"/media/seed/loma-hp.webp","alt":{"id":"Daftar signature di HP, setiap menu dengan fotonya","en":"The signature list on phone, each plate with its photo"},"width":600,"height":1298}]},{"title":{"id":"Lima tempat duduk","en":"Five places to sit"},"text":{"id":"La Sala, El Salón, El Jardín, La Terraza, dan El Bar bisa dipilih satu per satu, masing-masing dengan foto dan suasananya. Tombol reservasinya ikut berganti nama, dan tempat duduk itu sudah terpilih saat formulir reservasi terbuka.","en":"La Sala, El Salón, El Jardín, La Terraza and El Bar can be chosen one at a time, each with its photo and mood. The reserve button takes the space''s name, and that seating is already selected when the reservation form opens."},"images":[{"url":"/media/seed/loma-ruang.webp","alt":{"id":"Five places to sit dengan El Jardín terpilih: taman berlampu dengan bantal duduk di bawah pepohonan","en":"Five places to sit with El Jardín selected: a lantern-lit garden with floor cushions under the trees"},"width":1600,"height":1000}]},{"title":{"id":"La Carta","en":"La Carta"},"text":{"id":"Carta berisi 33 menu dalam delapan kategori, dari Signature sampai Without Spirits. Navigasi kategori menempel di sisi halaman, dan foto signature menemani daftar menu.","en":"The carta holds 33 items in eight courses, from Signature to Without Spirits. The course navigation stays at the side of the page, and a signature photo keeps the list company."},"images":[{"url":"/media/seed/loma-carta.webp","alt":{"id":"La Carta: kategori Signature dan To Begin, navigasi kategori di kiri, foto Grilled Octopus di kanan","en":"La Carta: the Signature and To Begin courses, the course navigation on the left, a Grilled Octopus photo on the right"},"width":1600,"height":1000},{"url":"/media/seed/loma-hp-carta.webp","alt":{"id":"La Carta di HP dengan navigasi kategori di atas","en":"La Carta on phone with the course navigation at the top"},"width":600,"height":1298}]},{"title":{"id":"Historia","en":"Historia"},"text":{"id":"Halaman kisah memperkenalkan tanda jaguar, palet warna yang diambil dari material ruangan (walnut, kayu bergalur, linen zaitun, travertine), dapurnya, dan enam ikon yang digambar tangan seperti cap.","en":"The story page introduces the jaguar mark, a palette taken from the room''s materials (walnut, fluted wood, olive linen, travertine), the kitchen, and six hand-drawn icons cut like stamps."},"images":[{"url":"/media/seed/loma-historia.webp","alt":{"id":"What the room is made of: empat foto material dengan nama warnanya","en":"What the room is made of: four material photos with their colour names"},"width":1600,"height":1000}]},{"title":{"id":"Reservar","en":"Reservar"},"text":{"id":"Reservasi berjalan dalam enam langkah. Hari Senin otomatis tertutup, jam hanya muncul dalam jam buka, tamu dibatasi enam orang dengan jalan pintas ke private dining, lalu ringkasannya tampil dengan kalimat Nos vemos pronto.","en":"Reservations run in six steps. Mondays close on their own, times only appear within opening hours, guests are capped at six with a shortcut to private dining, and the summary closes with Nos vemos pronto."},"images":[{"url":"/media/seed/loma-reservasi.webp","alt":{"id":"Formulir reservasi: tanggal, jam, tiga tamu, El Jardín, dan acara Celebration terpilih","en":"The reservation form: a date, a time, three guests, El Jardín and the Celebration occasion selected"},"width":1600,"height":1000},{"url":"/media/seed/loma-hp-reservasi.webp","alt":{"id":"Konfirmasi Nos vemos pronto dengan ringkasan reservasi di HP","en":"The Nos vemos pronto confirmation with the reservation summary on phone"},"width":600,"height":1298}]}]},{"type":"flow","title":{"id":"Alur reservasi","en":"Booking a table"},"steps":[{"id":"Pilih tanggal; hari Senin tutup","en":"Pick a date; Mondays are closed"},{"id":"Pilih jam antara 5.30 dan 10.00 malam","en":"Choose a time between 5.30 and 10.00 PM"},{"id":"Atur jumlah tamu, satu sampai enam","en":"Set the guests, one to six"},{"id":"Pilih tempat duduk bila ingin","en":"Choose a seating area if you like"},{"id":"Pilih acaranya bila ingin","en":"Choose the occasion if you like"},{"id":"Isi nama dan email, lalu kirim permintaan","en":"Enter a name and email, then send the request"}]},{"type":"decisions","title":{"id":"Keputusan desain","en":"Design decisions"},"items":[{"title":{"id":"Foto yang terasa hidup, dengan cadangan","en":"Photos that feel alive, with a fallback"},"text":{"id":"Foto dirender lewat WebGL supaya bisa melengkung halus saat digulir. Di balik itu tetap ada gambar biasa, jadi semua foto tampil di browser tanpa WebGL.","en":"The photographs render through WebGL so they can bend gently on scroll. Ordinary images sit underneath, so every photo still shows in a browser without WebGL."}},{"title":{"id":"Warna dari ruangannya","en":"Colours from the room"},"text":{"id":"Palet Boho Black, Tribal Brown, Nato Green, dan Silk Grey diambil dari walnut, kayu bergalur, linen, dan travertine di ruang makan, jadi situs dan ruangannya bicara dengan bahasa yang sama.","en":"The Boho Black, Tribal Brown, Nato Green and Silk Grey palette comes from the walnut, fluted wood, linen and travertine in the dining room, so the site and the room speak the same language."}},{"title":{"id":"Detail yang digambar tangan","en":"Details drawn by hand"},"text":{"id":"Enam ikon tempat (entrada, meja host, ruang tunggu, private dining, bar, teras) digambar seperti cap lama dan dipakai dari papan nama sampai kantong kertas.","en":"Six place icons (entrance, host desk, waiting area, private dining, bar, terrace) are drawn like old stamps and used from signage to paper bags."}},{"title":{"id":"Reservasi yang jujur","en":"An honest booking form"},"text":{"id":"Formulir hanya menawarkan yang benar-benar bisa dipesan: hari Senin tutup, jam sesuai jam buka, dan rombongan tujuh orang atau lebih diarahkan ke private dining.","en":"The form only offers what can really be booked: Mondays closed, times within opening hours, and parties of seven or more sent to private dining."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"4","label":{"id":"halaman dalam satu file","en":"pages in one file"}},{"value":"33","label":{"id":"menu dalam delapan kategori","en":"items across eight courses"}},{"value":"5","label":{"id":"tempat duduk untuk dipilih","en":"places to sit"}},{"value":"6","label":{"id":"langkah memesan meja","en":"steps to book a table"}}],"stack":{"id":"Dibuat dengan HTML, CSS, dan JavaScript, GSAP (ScrollTrigger, Flip, SplitText), dan Three.js untuk foto WebGL. Satu file, berjalan tanpa server.","en":"Built with HTML, CSS and JavaScript, GSAP (ScrollTrigger, Flip, SplitText) and Three.js for the WebGL photographs. One file that runs without a server."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'loma') on conflict (project_slug) do nothing;
insert into public.case_studies (project_slug, published, data) select 'rua', true, '{"subtitle":{"id":"Situs kafe Vietnam di Saigon: maskot kura-kura, menu yang dipesan untuk satu meja, dan jam buka yang selalu tepat.","en":"A Vietnamese café site for Saigon: a turtle mascot, a menu you order for the table, and opening hours that are always right."},"labels":{"client":"RUA","field":{"id":"Kafe Vietnam","en":"Vietnamese café"},"role":{"id":"Desain situs, interaksi, dan front-end, bersama Invisual Studio","en":"Site design, interaction and front-end, with Invisual Studio"},"year":"2026"},"cover":{"url":"/media/seed/rua-hero.webp","alt":{"id":"Beranda RUA: wordmark merah besar di latar kuning, maskot kura-kura memegang menu dan menyapa Xin chào","en":"RUA homepage: a large red wordmark on yellow, the turtle mascot holding a menu and saying Xin chào"},"width":1600,"height":1000},"theme":{"wall":"#FFF7C7","ink":"#5B0808","muted":"#7B0808","accent":"#BA0C0C","btnBg":"#BA0C0C","btnInk":"#FFF7C7"},"blocks":[{"type":"prose","title":{"id":"Situasinya","en":"The situation"},"paragraphs":[{"id":"RUA adalah merek kafe Vietnam yang dibangun dari kehangatan, rasa akrab, dan sedikit karakter. Identitasnya mengambil inspirasi dari budaya visual Vietnam: papan nama lama, gambar tangan, dan suasana ramai tempat makan sehari-hari, lalu menyatukannya dengan cara yang lebih berani dan kontemporer.","en":"RUA is a Vietnamese café brand built around warmth, familiarity, and a little bit of character. The identity takes inspiration from traditional Vietnamese visual culture, old signage, hand-drawn graphics, and the lively atmosphere of everyday food places, then brings them together in a bolder and more contemporary way."},{"id":"Pusatnya adalah maskot kura-kura yang terinspirasi kura-kura Danau Hoàn Kiếm, dibayangkan ulang sebagai pelayan kafe yang ramah: mengantar makanan, menyambut tamu, membawa nampan, dan muncul di kemasan, menu, papan nama, sampai aplikasi digital. Situsnya perlu terasa seperti kafe itu sendiri: berisik, hangat, dan mengundang untuk memesan bersama.","en":"At the center of RUA is a turtle mascot inspired by the Hoan Kiem turtle, reimagined as a friendly café server who serves food, welcomes guests, carries trays and appears across packaging, menus, signage and digital applications. The site had to feel like the café itself: loud, warm and made for ordering together."},{"id":"Proyek ini dikerjakan di Invisual Studio sebagai satu file preview berisi satu halaman panjang dengan sepuluh bagian, lengkap di desktop dan HP. Situsnya belum tayang, dan pesanannya tidak dikirim ke mana pun.","en":"The project was made at Invisual Studio as a single preview file: one long page in ten sections, complete on desktop and phone. The site isn''t live yet, and its orders are sent nowhere."}]},{"type":"features","title":{"id":"Satu halaman, satu meja panjang","en":"One page, one long table"},"items":[{"title":{"id":"Kura-kura di depan pintu","en":"A turtle at the door"},"text":{"id":"Situs dibuka dengan rolling door yang naik setelah hitungan sampai 100. Wordmark RUA meregang ke atas, kura-kura melompat dari tepi bawah sambil memegang menu, dan bila disentuh ia mengucapkan kalimat lain, dari Xin chào sampai Ăn ngon nhé. Bagian Come, we eat menghadirkan tiga kura-kura pelayan dan kisah namanya: rùa berarti kura-kura.","en":"The site opens with a roll-up shutter that lifts once the count reaches 100. The RUA wordmark stretches up, the turtle pops up from the bottom edge holding the menu, and a tap makes him say another line, from Xin chào to Ăn ngon nhé. Come, we eat brings in three turtle servers and the story of the name: rùa means turtle."},"images":[{"url":"/media/seed/rua-hp.webp","alt":{"id":"Come, we eat di HP: judul kuning di latar merah dan tiga kura-kura pelayan","en":"Come, we eat on phone: a yellow headline on red and three turtle servers"},"width":600,"height":1298}]},{"title":{"id":"Jangan lupa saus","en":"Don''t skip the sauce"},"text":{"id":"Botol saus cabai bisa diremas. Setiap remasan memercikkan saus ke judul dan menaikkan tingkat pedasnya, dari Mild sampai RUA hot, lalu OK, that’s plenty.","en":"The chili bottle can be squeezed. Every squeeze splashes sauce across the headline and raises the heat, from Mild to RUA hot, then OK, that’s plenty."},"images":[{"url":"/media/seed/rua-saus.webp","alt":{"id":"Judul Don''t skip the sauce dengan percikan saus, botol cabai di kanan atas bertuliskan Very hot","en":"The Don''t skip the sauce headline splashed with sauce, the chili bottle top right reading Very hot"},"width":1600,"height":1000}]},{"title":{"id":"Menu yang tersaji","en":"A menu that plates itself"},"text":{"id":"Menu berisi 17 makanan dan minuman dalam tiga tab: Big eats, Good sips, dan Extra bites. Di desktop, gambar hidangannya mendarat di piring saat namanya disorot; menu yang pedas diberi tanda cabai. Di bawahnya, carousel Hot eats on the go bisa digeser, dan tombol Add-nya langsung menaruh hidangan di meja.","en":"The menu holds 17 dishes and drinks in three tabs: Big eats, Good sips and Extra bites. On desktop, the dish lands on the plate as you point at its name, and the spicy ones carry a chili. Below it, the Hot eats on the go carousel can be dragged, and its Add button puts a dish on the table straight away."},"images":[{"url":"/media/seed/rua-menu.webp","alt":{"id":"Tab Big eats dengan Phở bò disorot dan gambar mangkuknya di piring","en":"The Big eats tab with Phở bò highlighted and its bowl on the plate"},"width":1600,"height":1000},{"url":"/media/seed/rua-hp-menu.webp","alt":{"id":"Menu di HP: tab di atas dan setiap hidangan dengan tombol tambah","en":"The menu on phone: tabs at the top and every dish with an add button"},"width":600,"height":1298}]},{"title":{"id":"Pesan untuk satu meja","en":"Order for the table"},"text":{"id":"Tombol + membuat hidangan terbang ke Your table. Di sana jumlahnya bisa diatur, totalnya terlihat, dan kura-kura bereaksi dengan wajah yang berbeda. Send to the counter mencetak tiket bernomor untuk ditunjukkan di kasir; tiket itu menyebut dengan jelas bahwa ini preview dan tidak ada yang dikirim.","en":"The + button sends a dish flying to Your table. There the amounts can be changed, the total shows, and the turtle reacts with a different face. Send to the counter prints a numbered ticket to show at the counter, and the ticket says plainly that this is a preview and nothing is sent."},"images":[{"url":"/media/seed/rua-meja.webp","alt":{"id":"Your table terbuka: nampan berisi hidangan, daftar pesanan dengan jumlahnya, dan total 300K","en":"Your table open: a tray of dishes, the order list with amounts and a 300K total"},"width":1600,"height":1000},{"url":"/media/seed/rua-hp-tiket.webp","alt":{"id":"Tiket Nº 027 di HP dengan daftar pesanan dan total","en":"Ticket Nº 027 on phone with the order list and total"},"width":600,"height":1298}]},{"title":{"id":"Panas di dalam kotak","en":"Hot stuff inside"},"text":{"id":"Bagian bawa pulang memperlihatkan kemasan RUA dalam empat langkah: lembaran datar, label, kotak terlipat, dan mangkuk sup. Di desktop langkahnya berganti saat halaman digulir; di HP berganti sendiri dan bisa dipilih.","en":"The takeaway section shows RUA''s packaging in four steps: the flat pack, the label, the folded box and the soup tub. On desktop the steps change as the page scrolls; on phones they change on their own and can be picked."},"images":[{"url":"/media/seed/rua-kotak.webp","alt":{"id":"Hot stuff inside: kotak merah RUA terlipat dengan kura-kura koki, langkah Box it terpilih","en":"Hot stuff inside: the folded red RUA box with a turtle chef, the Box it step selected"},"width":1600,"height":1000}]},{"title":{"id":"Pull up here!","en":"Pull up here!"},"text":{"id":"Papan Open/Closed tergantung dan berayun saat disentuh atau saat halaman digulir cepat. Papan itu membaca jam Saigon, jadi pengunjung dari mana pun tahu apakah RUA sedang buka. Di bawahnya ada foto toko, empat cara makan di RUA, dan kolase papan-papan di dalam kafe.","en":"The Open/Closed sign hangs and swings when touched or when the page scrolls fast. It reads the time in Saigon, so visitors anywhere know whether RUA is open right now. Below it come the storefront photo, the four ways to eat at RUA and a collage of the signs inside."},"images":[{"url":"/media/seed/rua-tempat.webp","alt":{"id":"Pull up here! dengan papan We are Open dan jam Saigon di bawahnya, foto toko RUA di bawah","en":"Pull up here! with the We are Open sign and the Saigon time beneath it, the RUA storefront below"},"width":1600,"height":1000}]},{"title":{"id":"Little Stool Club","en":"Little Stool Club"},"text":{"id":"Dinding stiker bisa diisi sendiri: ketuk tempat kosong untuk menempel stiker baru, geser stiker ke mana saja, atau kelupas semuanya. Di bawahnya ada merchandise RUA dan enam unggahan Instagram.","en":"The sticker wall is yours to fill: tap an empty spot to slap on a new sticker, drag any sticker around, or peel them all off. Below it sit RUA''s merchandise and six Instagram posts."},"images":[{"url":"/media/seed/rua-stiker.webp","alt":{"id":"Dinding stiker Little Stool Club: wajah kura-kura, wordmark RUA, banh mi, dan stiker Extra sauce please","en":"The Little Stool Club sticker wall: turtle faces, the RUA wordmark, a bánh mì and an Extra sauce please sticker"},"width":1600,"height":1000}]}]},{"type":"flow","title":{"id":"Alur memesan untuk satu meja","en":"Ordering for the table"},"steps":[{"id":"Ketuk + pada hidangan di menu atau carousel","en":"Tap + on a dish in the menu or the carousel"},{"id":"Hidangannya terbang ke Your table","en":"The dish flies to Your table"},{"id":"Atur jumlah setiap hidangan","en":"Change how many of each"},{"id":"Periksa totalnya","en":"Check the total"},{"id":"Kirim dengan Send to the counter","en":"Send it with Send to the counter"},{"id":"Tunjukkan tiket bernomor di Order here","en":"Show the numbered ticket at Order here"}]},{"type":"decisions","title":{"id":"Keputusan desain","en":"Design decisions"},"items":[{"title":{"id":"Gerak dari GIF mereknya","en":"Motion from the brand''s GIFs"},"text":{"id":"Maskot muncul dari tepi bawah dengan kabur gerak lalu memantul. Gerak diam, goyangan, dan stiker yang ditempel ditahan dua frame seperti stop-motion, dan garisnya bergetar delapan kali per detik seperti gambar tangan.","en":"Mascots pop up from the bottom edge with a motion-blur whoosh and an overshoot. Idles, wiggles and sticker slaps hold every frame twice like stop-motion, and the lines boil eight times a second like hand drawing."}},{"title":{"id":"Jam buka dalam waktu Saigon","en":"Opening hours in Saigon time"},"text":{"id":"Status di header dan papan Open/Closed dihitung dari jam Saigon (10.00 sampai 22.00), bukan jam di perangkat pengunjung, dan diperbarui setiap 30 detik.","en":"The status in the header and the Open/Closed sign are worked out from Saigon time (10AM to 10PM), not the visitor''s own clock, and refresh every 30 seconds."}},{"title":{"id":"Meja yang menunggu","en":"A table that waits for you"},"text":{"id":"Pesanan disimpan di perangkat pengunjung, jadi saat kembali mejanya masih ada. Bila browser menolak penyimpanan, situs tetap berjalan.","en":"The order is kept on the visitor''s device, so the table is still there when they come back. If the browser refuses storage, the site keeps working."}},{"title":{"id":"Main-main, tetap mudah dipakai","en":"Playful, still easy to use"},"text":{"id":"Kursor sumpit hanya muncul untuk mouse. Hidangan bisa ditambah dengan keyboard, Escape menutup Your table, dan bila pengunjung meminta gerak dikurangi, animasinya berhenti.","en":"The chopstick cursor only appears for a mouse. Dishes can be added from the keyboard, Escape closes Your table, and when visitors ask for reduced motion, the animation stops."}}]},{"type":"numbers","title":{"id":"Dalam angka","en":"By the numbers"},"facts":[{"value":"10","label":{"id":"bagian dalam satu halaman","en":"sections on one page"}},{"value":"17","label":{"id":"makanan dan minuman di menu","en":"dishes and drinks on the menu"}},{"value":"13","label":{"id":"wajah kura-kura","en":"turtle faces"}},{"value":"96","label":{"id":"gambar vektor dalam satu file","en":"vector drawings in a single file"}}],"stack":{"id":"Dibuat dengan HTML, CSS, dan JavaScript, GSAP (ScrollTrigger, Draggable, Inertia, SplitText), dan Lenis untuk gulir halus. Satu file, berjalan tanpa server.","en":"Built with HTML, CSS and JavaScript, GSAP (ScrollTrigger, Draggable, Inertia, SplitText) and Lenis for smooth scrolling. One file that runs without a server."}}]}'::jsonb where exists (select 1 from public.projects where slug = 'rua') on conflict (project_slug) do nothing;
